  */
 function graphBuildFixtureView() {
   const fixture = GRAPH_VIEW_STATE.fixture;
   const p = fixture.p || graphFixtureRestartVector(fixture.restart || "uniform");
   const nodes = REFERENCE_GRAPH.nodes.map((nd) => ({
