      return { n: 0, nUsers: 0, kind: "dense", step: function () { return null; }, dispose: function () {} };
    }
    const rows = new Array(n);
    for (let i = 0; i < n; i++) {
      const source = explicit[i];
      const row = new Float32Array(n);
      for (let j = 0; j < n; j++) row[j] = Number(source && source[j]) || 0;
      rows[i] = row;
    }
    const maskData = new Float32Array(n);
    const providedMask = spec.danglingMask;
    if (providedMask && providedMask.length === n) {
      for (let i = 0; i < n; i++) maskData[i] = providedMask[i] ? 1 : 0;
    } else {
      for (let i = 0; i < n; i++) {
        let sum = 0;
        for (let j = 0; j < n; j++) sum += rows[i][j];
        if (sum <= 0) maskData[i] = 1;
