+        tf.mul(vTensor.slice([nUsers], [nMovies]), base),
+      );
+      const nextUser = tf.add(
+        tf.mul(tf.matMul(tR, sMovie.expandDims(1), false, false).squeeze(), alphaTensor),
+        tf.mul(vTensor.slice([0], [nUsers]), base),
+      );
+      return tf.concat([nextUser, nextMovie]);
+    },
+    dispose: function () {
+      if (disposed) return;
+      disposed = true;
+      tR.dispose();
+      tInvUser.dispose();
+      tInvMovie.dispose();
+      tDanglingUser.dispose();
+      tDanglingMovie.dispose();
+    },
+  };
+}
+
+/**
+ * Run the batched TensorFlow.js power iteration for one restart distribution.
+ *
+ * Update (readme.md sections 3.3/3.4):
+ *   p_0 = v ;  p_next = alpha * (Q^T p + d * v) + (1 - alpha) * v
+ * which is equivalently `alpha * Q^T p + ((1 - alpha) + alpha * d) * v`, where
+ * `d` is the probability mass currently sitting on zero-degree nodes (`step`
+ * derives `d` from the matrix's own dangling mask / degrees).
+ *
+ * Stops when the L1 difference `sum_j |p_next[j] - p[j]|` is below `tol`, or
+ * after `maxIter` updates. Reaching the cap is NOT convergence: `converged` is
+ * true only when the tolerance was met before the cap. Every tensor created
+ * here (and the machine's own tensors) is disposed before returning, so
+ * repeated runs do not accumulate memory. Reading results is synchronous
+ * (`dataSync`) because the page's caller contract is synchronous; backend
+ * readiness is established once by `script.js` at startup.
+ *
+ * @param {{n:number, step:Function, dispose:Function}} machine From
+ *   {@link graphTransitionMachine}.
+ * @param {number} alpha Link-following probability.
+ * @param {ArrayLike<number>} restart Normalized restart distribution over node
+ *   indices (uniform for `pageRank`, one-hot for `personalizedPageRank`).
+ * @param {number} tol L1 convergence tolerance.
+ * @param {number} maxIter Iteration cap.
+ * @returns {PageRankResult} `{p, iterations, residual, converged}`.
+ */
+function graphPowerIterate(machine, alpha, restart, tol, maxIter) {
+  if (typeof tf === "undefined" || tf === null) {
+    throw new Error("graph propagation: TensorFlow.js (`tf`) is required but is not defined");
+  }
+  const n = machine.n;
+  if (n <= 0) {
+    machine.dispose();
+    return { p: new Float64Array(0), iterations: 0, residual: 0, converged: true };
+  }
+
+  const alphaTensor = tf.scalar(Number(alpha), "float32");
+  const vTensor = tf.tensor1d(Float32Array.from(restart), "float32");
+  let p = tf.tensor1d(Float32Array.from(restart), "float32");
+  let iterations = 0;
+  let residual = Infinity;
+  let converged = false;
+  try {
+    while (iterations < maxIter) {
+      const next = tf.tidy(function () { return machine.step(p, alphaTensor, vTensor); });
+      const diff = tf.tidy(function () { return tf.sum(tf.abs(tf.sub(next, p))); });
+      residual = Number(diff.dataSync()[0]);
+      diff.dispose();
+      p.dispose();
+      p = next;
+      iterations += 1;
+      if (residual < tol) {
+        converged = true;
+        break;
+      }
+    }
+    const data = p.dataSync();
+    const out = new Float64Array(n);
+    for (let i = 0; i < n; i++) out[i] = data[i];
+    return { p: out, iterations: iterations, residual: residual, converged: converged };
+  } finally {
+    p.dispose();
+    alphaTensor.dispose();
+    vTensor.dispose();
+    machine.dispose();
+  }
+}
