    if (seedNode < 0) {
      const raw = Number(userId);
      if (!Number.isInteger(raw) || raw < 0 || raw >= n) {
        throw new Error("personalizedPageRank: cannot map restart node " + userId + " to a node in [0, " + n + ")");
