        // collects alpha * sum_i R[u][i]/deg(i) * pMovie[i] (readme.md 3.3/3.5).
        const nextMovie = tf.add(
          tf.mul(tf.matMul(tR, sUser.expandDims(1), true, false).squeeze(), alphaTensor),
          tf.mul(vTensor.slice([nUsers], [nMovies]), base),
        );
