// ---------------------------------------------------------------------------
// Small helpers (private, all graph-prefixed to avoid collisions)
// ---------------------------------------------------------------------------

/**
 * Build a TensorFlow.js propagation machine for `pageRank` /
 * `personalizedPageRank`.
 *
 * Two shapes are supported and both expose the same tiny interface
 * (`{ n, nUsers, kind, step(p, alphaTensor, vTensor), dispose() }`):
 *
 *  - "dense" - an explicit, already row-normalized square transition supplied as
 *    `spec` ({@link TransitionSpec}), e.g. `REFERENCE_GRAPH.transition`. `Q` is
 *    used as-is (never re-normalized); `danglingMask` is read by position.
 *  - "bipartite" - the global `GRAPH` from `buildGraph`. Instead of
 *    materializing the n x n square adjacency, the two off-diagonal blocks are
 *    represented with `R` and its transpose and normalized per node as a vector
 *    (user rows by user degree, movie rows by movie degree), so the batched
 *    update is `alpha * (R^T * sU)` / `alpha * (R * sM)` (readme.md section 3.5).
 *
 * Indexing: node order is users `[0, nUsers)` then movies
 * `[nUsers, nUsers + nMovies)`, exactly as `buildGraph`. `v` (the restart
 * distribution) is passed to `step` as a node-indexed tensor.
 *
 * @param {TransitionSpec|undefined} spec Explicit transition, or undefined to
 *   use the global `GRAPH`.
 * @returns {{n:number, nUsers:number, kind:string, step:Function, dispose:Function}}
 * @throws {Error} when TensorFlow.js is unavailable, or when `spec` is absent
 *   and no global `GRAPH` (from `buildGraph`) is available.
 */
function graphTransitionMachine(spec) {
  if (typeof tf === "undefined" || tf === null) {
    throw new Error("graph propagation: TensorFlow.js (`tf`) is required but is not defined");
  }

  const explicit = spec && Array.isArray(spec.Q) ? spec.Q : null;
  if (explicit) {
    const n = explicit.length;
    if (n <= 0) {
      return {
        n: 0, nUsers: 0, kind: "dense",
        step: function () { return null; },
        dispose: function () {},
      };
    }
    const flat = new Float32Array(n * n);
    for (let i = 0; i < n; i++) {
      const row = explicit[i];
      for (let j = 0; j < n; j++) flat[i * n + j] = Number(row && row[j]) || 0;
    }
    const maskData = new Float32Array(n);
    const provided = spec.danglingMask;
    if (provided && provided.length === n) {
      for (let i = 0; i < n; i++) maskData[i] = provided[i] ? 1 : 0;
    } else {
      for (let i = 0; i < n; i++) {
        let sum = 0;
        for (let j = 0; j < n; j++) sum += flat[i * n + j];
        if (sum <= 0) maskData[i] = 1;
      }
    }
    const tQ = tf.tensor2d(flat, [n, n], "float32");
    const tMask = tf.tensor1d(maskData, "float32");
    let disposed = false;
    return {
      n: n,
      nUsers: 0,
      kind: "dense",
      step: function (p, alphaTensor, vTensor) {
        // p_next = alpha * (Q^T p) + ((1 - alpha) + alpha * d) * v
        const qTp = tf.matMul(tQ, p.expandDims(1), true, false).squeeze();
        const danglingMass = tf.sum(tf.mul(p, tMask));
        const base = tf.add(tf.scalar(1).sub(alphaTensor), tf.mul(alphaTensor, danglingMass));
        return tf.add(tf.mul(qTp, alphaTensor), tf.mul(vTensor, base));
      },
      dispose: function () {
        if (disposed) return;
        disposed = true;
        tQ.dispose();
        tMask.dispose();
      },
    };
  }

  const graph = typeof GRAPH !== "undefined" ? GRAPH : null;
  if (!graph || !Array.isArray(graph.R) || !Number.isFinite(graph.nUsers) || !Number.isFinite(graph.nMovies)) {
    throw new Error("graph propagation: no transition supplied and no global GRAPH is available (build the graph first)");
  }
  const nUsers = graph.nUsers;
  const nMovies = graph.nMovies;
  const n = nUsers + nMovies;
  if (nUsers <= 0 || nMovies <= 0) {
    // Degenerate graph: no edges exist, so every node is dangling. Fall back to
    // a dense all-zero transition (every row flagged dangling).
    const zeros = new Array(n);
    for (let i = 0; i < n; i++) zeros[i] = new Array(n).fill(0);
    return graphTransitionMachine({ Q: zeros, danglingMask: new Array(n).fill(true) });
  }

  const R = graph.R;
  const rData = new Float32Array(nUsers * nMovies);
  const invUser = new Float32Array(nUsers);
  const invMovie = new Float32Array(nMovies);
  const danglingUser = new Float32Array(nUsers);
  const danglingMovie = new Float32Array(nMovies);
  const degreeUser = new Float32Array(nUsers);
  const degreeMovie = new Float32Array(nMovies);
  for (let u = 0; u < nUsers; u++) {
    const row = R[u];
    if (!Array.isArray(row)) continue;
    for (let i = 0; i < nMovies; i++) {
      const weight = Number(row[i]) || 0;
      if (weight !== 0) {
        rData[u * nMovies + i] = weight;
        degreeUser[u] += weight;
        degreeMovie[i] += weight;
      }
    }
  }
  for (let u = 0; u < nUsers; u++) {
    if (degreeUser[u] > 0) invUser[u] = 1 / degreeUser[u];
    else danglingUser[u] = 1;
  }
  for (let i = 0; i < nMovies; i++) {
    if (degreeMovie[i] > 0) invMovie[i] = 1 / degreeMovie[i];
    else danglingMovie[i] = 1;
  }

  const tR = tf.tensor2d(rData, [nUsers, nMovies], "float32");
  const tInvUser = tf.tensor1d(invUser, "float32");
  const tInvMovie = tf.tensor1d(invMovie, "float32");
  const tDanglingUser = tf.tensor1d(danglingUser, "float32");
  const tDanglingMovie = tf.tensor1d(danglingMovie, "float32");
  let disposed = false;
  return {
    n: n,
    nUsers: nUsers,
    nMovies: nMovies,
    kind: "bipartite",
    step: function (p, alphaTensor, vTensor) {
      // Split the node-indexed distribution into its user and movie blocks.
      const pUser = tf.slice(p, [0], [nUsers]);
      const pMovie = tf.slice(p, [nUsers], [nMovies]);
      // Vector degree normalization; dangling nodes scale to 0 and are handled
      // by the dangling-mass term below, never by a division by zero.
      const sUser = tf.mul(pUser, tInvUser);
      const sMovie = tf.mul(pMovie, tInvMovie);
      const danglingMass = tf.add(
        tf.sum(tf.mul(pUser, tDanglingUser)),
        tf.sum(tf.mul(pMovie, tDanglingMovie)),
      );
      const base = tf.add(tf.scalar(1).sub(alphaTensor), tf.mul(alphaTensor, danglingMass));
      // Movie i collects alpha * sum_u R[u][i]/deg(u) * pUser[u]; user u collects
      // alpha * sum_i R[u][i]/deg(i) * pMovie[i] (readme.md sections 3.3/3.5).
      const nextMovie = tf.add(
        tf.mul(tf.matMul(tR, sUser.expandDims(1), true, false).squeeze(), alphaTensor),
        tf.mul(vTensor.slice([nUsers], [nMovies]), base),
      );
      const nextUser = tf.add(
        tf.mul(tf.matMul(tR, sMovie.expandDims(1), false, false).squeeze(), alphaTensor),
        tf.mul(vTensor.slice([0], [nUsers]), base),
      );
      return tf.concat([nextUser, nextMovie]);
    },
    dispose: function () {
      if (disposed) return;
      disposed = true;
      tR.dispose();
      tInvUser.dispose();
      tInvMovie.dispose();
      tDanglingUser.dispose();
      tDanglingMovie.dispose();
    },
  };
}

/**
 * Run the batched TensorFlow.js power iteration for one restart distribution.
 *
 * Update (readme.md sections 3.3/3.4):
 *   p_0 = v ;  p_next = alpha * (Q^T p + d * v) + (1 - alpha) * v
 * which is equivalently `alpha * Q^T p + ((1 - alpha) + alpha * d) * v`, where
 * `d` is the probability mass currently sitting on zero-degree nodes (`step`
 * derives `d` from the matrix's own dangling mask / degrees).
 *
 * Stops when the L1 difference `sum_j |p_next[j] - p[j]|` is below `tol`, or
 * after `maxIter` updates. Reaching the cap is NOT convergence: `converged` is
 * true only when the tolerance was met before the cap. Every tensor created
 * here (and the machine's own tensors) is disposed before returning, so
 * repeated runs do not accumulate memory. Reading results is synchronous
 * (`dataSync`) because the page's caller contract is synchronous; backend
 * readiness is established once by `script.js` at startup.
 *
 * @param {{n:number, step:Function, dispose:Function}} machine From
 *   {@link graphTransitionMachine}.
 * @param {number} alpha Link-following probability.
 * @param {ArrayLike<number>} restart Normalized restart distribution over node
 *   indices (uniform for `pageRank`, one-hot for `personalizedPageRank`).
 * @param {number} tol L1 convergence tolerance.
 * @param {number} maxIter Iteration cap.
 * @returns {PageRankResult} `{p, iterations, residual, converged}`.
 */
function graphPowerIterate(machine, alpha, restart, tol, maxIter) {
  if (typeof tf === "undefined" || tf === null) {
    throw new Error("graph propagation: TensorFlow.js (`tf`) is required but is not defined");
  }
  const n = machine.n;
  if (n <= 0) {
    machine.dispose();
    return { p: new Float64Array(0), iterations: 0, residual: 0, converged: true };
  }

  const alphaTensor = tf.scalar(Number(alpha), "float32");
  const vTensor = tf.tensor1d(Float32Array.from(restart), "float32");
  let p = tf.tensor1d(Float32Array.from(restart), "float32");
  let iterations = 0;
  let residual = Infinity;
  let converged = false;
  try {
    while (iterations < maxIter) {
      const next = tf.tidy(function () { return machine.step(p, alphaTensor, vTensor); });
      const diff = tf.tidy(function () { return tf.sum(tf.abs(tf.sub(next, p))); });
      residual = Number(diff.dataSync()[0]);
      diff.dispose();
      p.dispose();
      p = next;
      iterations += 1;
      if (residual < tol) {
        converged = true;
        break;
      }
    }
    const data = p.dataSync();
    const out = new Float64Array(n);
    for (let i = 0; i < n; i++) out[i] = data[i];
    return { p: out, iterations: iterations, residual: residual, converged: converged };
  } finally {
    p.dispose();
    alphaTensor.dispose();
    vTensor.dispose();
    machine.dispose();
  }
}

