const fs = require("fs");
const path = require("path");
const vm = require("vm");

const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const TF = "C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js";
const tf = require(TF);

let failures = 0;
function assert(cond, label) {
  if (cond) console.log("  assert ok: " + label);
  else { failures++; console.log("  ASSERT FAIL: " + label); }
}
function close(a, b, tol) { return Math.abs(a - b) <= tol; }
function maxAbs(a, b) { let m = 0; for (let i = 0; i < a.length; i++) m = Math.max(m, Math.abs(a[i] - b[i])); return m; }
function sum(a) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i]; return s; }

function makeElement(id) {
  return {
    id: id, textContent: "", innerHTML: "", value: "0.85", checked: false,
    className: "", disabled: false, style: {}, dataset: {},
    classList: { add: function(){}, remove: function(){}, toggle: function(){}, contains: function(){ return false; } },
    addEventListener: function(){}, removeEventListener: function(){},
    appendChild: function(){}, removeChild: function(){},
    setAttribute: function(){}, getAttribute: function(){ return null; },
    querySelector: function(){ return null; }, querySelectorAll: function(){ return []; },
    focus: function(){}, click: function(){},
    scrollTop: 0, scrollHeight: 0, options: [], selectedIndex: 0, length: 0,
  };
}
const elements = new Map();
function getEl(id) {
  if (!elements.has(id)) elements.set(id, makeElement(id));
  return elements.get(id);
}

const sandbox = {
  console: console,
  tf: tf,
  setTimeout: setTimeout, clearTimeout: clearTimeout,
  setInterval: setInterval, clearInterval: clearInterval,
  fetch: async function (url) {
    const file = path.join(WEEK6, String(url).split("?")[0]);
    const text = fs.readFileSync(file, "utf8");
    return { ok: true, status: 200, text: async function () { return text; } };
  },
  document: {
    readyState: "loading",
    getElementById: getEl,
    addEventListener: function(){}, removeEventListener: function(){},
    createElement: function (t) { return makeElement(t); },
    querySelector: function(){ return null; },
    querySelectorAll: function(){ return []; },
    body: makeElement("body"),
    title: "",
  },
  navigator: { userAgent: "node-vm-runner" },
  performance: { now: function () { return Date.now(); } },
  URL: URL, URLSearchParams: URLSearchParams,
  requestAnimationFrame: function (cb) { return setTimeout(cb, 0); },
  cancelAnimationFrame: clearTimeout,
  Blob: function Blob(){}, FileReader: function FileReader(){},
  atob: function (s) { return Buffer.from(s, "base64").toString("binary"); },
  btoa: function (s) { return Buffer.from(s, "binary").toString("base64"); },
};
const context = vm.createContext(sandbox);
vm.runInContext("window = globalThis; self = globalThis;", context);

function runFile(name) {
  const code = fs.readFileSync(path.join(WEEK6, name), "utf8");
  vm.runInContext(code, context, { filename: name });
  console.log("loaded " + name);
}
function evalIn(expr) { return vm.runInContext(expr, context); }

function printChecks(label, res) {
  console.log(label + " -> PASS=" + res.passed + " FAIL=" + res.failed + " PENDING=" + res.pending + " TOTAL=" + res.checks.length);
  res.checks.forEach(function (c, i) {
    console.log("  " + (i + 1) + ". [" + c.status + "] " + c.name + (c.detail ? " -- " + c.detail : ""));
  });
}

async function main() {
  runFile("data.js");
  runFile("graph.js");
  runFile("script.js");

  console.log("TF VERSION " + evalIn("tf.version.tfjs"));

  await evalIn("loadData()");
  evalIn(
    "(function () {" +
    "  var s = splitByTimestamp();" +
    "  HW6_SPLIT.train = s.train; HW6_SPLIT.val = s.val; HW6_SPLIT.test = s.test;" +
    "  HW6_MAX_MOVIE_ID = movies.reduce(function (m, movie) { return Math.max(m, movie.id); }, 0);" +
    "  hw6BuildSplitIndices(HW6_SPLIT);" +
    "})()"
  );
  const counts = evalIn(
    "({ train: HW6_SPLIT.train.length, val: HW6_SPLIT.val.length, test: HW6_SPLIT.test.length," +
    "  users: HW6_STATE.trainUserIds.length, candidates: HW6_STATE.candidateIds.length," +
    "  positivePairs: HW6_STATE.positivePairs })"
  );
  console.log("SPLIT " + JSON.stringify(counts));

  const run1 = evalIn("runSelfChecks({ textContent: '' })");
  printChecks("HARNESS RUN 1 (graph not built)", run1);

  evalIn("hw6HandleBuildGraph()");
  const graphInfo = evalIn(
    "(function () { var g = getGraph(); return g ? { nUsers: g.nUsers, nMovies: g.nMovies, nodeCount: g.nodeCount, positiveEdges: g.positiveEdges, zeroUsers: g.zeroDegreeUsers.length, zeroMovies: g.zeroDegreeMovies.length } : null; })()"
  );
  console.log("BUILT GRAPH " + JSON.stringify(graphInfo));

  const run2 = evalIn("runSelfChecks({ textContent: '' })");
  printChecks("HARNESS RUN 2 (graph built)", run2);

  const buildGraph = context.buildGraph;
  const rowNormalize = context.rowNormalize;
  const graphNeighbors = context.graphNeighbors;
  const hw6MakeSyntheticGraph = context.hw6MakeSyntheticGraph;

  // ---- Independent graph checks (from iteration 1) ----
  console.log("TEST G1: one user, one positive train movie");
  const g1 = buildGraph([{ userId: 1, movieId: 10, rating: 5, timestamp: 1000 }]);
  assert(g1.nUsers === 1 && g1.nMovies === 1 && g1.nodeCount === 2, "nodeCount=2, no padding node");
  assert(g1.R[0][0] === 1, "R[user][movie]=1");
  assert(JSON.stringify(graphNeighbors(g1, 0)) === "[1]", "user -> movie edge exists");
  assert(JSON.stringify(graphNeighbors(g1, 1)) === "[0]", "movie -> user edge exists");
  assert(g1.degree[0] === 1 && g1.degree[1] === 1, "degree 1 on both sides");
  assert(g1.positiveEdges === 1, "positiveEdges=1");
  assert(g1.userIndexOf.get(1) === 0 && g1.movieIndexOf.get(10) === 0, "contiguous maps");
  assert(g1.nodeOfUser(1) === 0 && g1.movieOfNode(1) === 10, "nodeOfUser/movieOfNode roundtrip");
  assert(g1.isUserNode(0) === true && g1.isUserNode(1) === false, "isUserNode split");
  const g1c = buildGraph([{ userId: 10, movieId: 10, rating: 4, timestamp: 1 }]);
  assert(g1c.nodeCount === 2 && g1c.R[0][0] === 1 && g1c.isUserNode(1) === false, "id collision userId=10 vs movieId=10 separated by node space");

  console.log("TEST G2: train ratings 5, 4, 3");
  const g2 = buildGraph([
    { userId: 1, movieId: 1, rating: 5, timestamp: 1 },
    { userId: 1, movieId: 2, rating: 4, timestamp: 2 },
    { userId: 1, movieId: 3, rating: 3, timestamp: 3 },
  ]);
  assert(JSON.stringify(Array.from(g2.R[0])) === "[1,1,0]", "5 and 4 give edges, 3 does not");
  assert(g2.positiveEdges === 2, "positiveEdges=2");
  assert(g2.degree[3] === 0 && g2.degree[0] === 2, "movie 3 degree 0; user degree 2");
  assert(JSON.stringify(g2.zeroDegreeMovies) === "[3]", "zeroDegreeMovies=[3]");

  console.log("TEST G3: rating>=4 present ONLY in validation/test must not enter the train graph");
  const trainOnly = [{ userId: 1, movieId: 1, rating: 3, timestamp: 1 }];
  const valTestOnly = [
    { userId: 1, movieId: 1, rating: 5, timestamp: 9 },
    { userId: 2, movieId: 77, rating: 5, timestamp: 9 },
  ];
  const g3 = buildGraph(trainOnly);
  assert(g3.R[0][0] === 0 && g3.degree[0] === 0, "val/test rating 5 for movie 1 creates NO edge (train rating was 3)");
  assert(g3.movieIndexOf.has(1) === true && g3.degree[g3.nUsers + 0] === 0, "train-observed movie 1 is a zero-degree node");
  assert(JSON.stringify(g3.zeroDegreeUsers) === "[1]" && JSON.stringify(g3.zeroDegreeMovies) === "[1]", "both ends listed zero-degree");
  assert(g3.movieIndexOf.has(77) === false && g3.userIndexOf.has(2) === false, "val/test-only ids (user 2, movie 77) absent from graph");
  const g3b = buildGraph(valTestOnly);
  assert(g3b.nodeCount === 4 && g3b.nUsers === 2 && g3b.nMovies === 2 && g3.positiveEdges === 0 && g3b.positiveEdges === 2, "graphs are independent: train graph has 0 positive edges, val/test list builds a separate object (2 users + 2 movies = 4 nodes)");
  const g3nonarray = buildGraph(undefined);
  assert(g3nonarray.nodeCount === 0 && g3nonarray.positiveEdges === 0 && Array.isArray(g3nonarray.R), "non-array train returns empty graph, no throw");

  console.log("TEST N1: row [0,2,2,0] normalizes to [0,0.5,0.5,0], sum=1");
  const n1graph = { nodeCount: 5, nUsers: 1, nMovies: 4, R: [[0, 2, 2, 0]] };
  const n1 = rowNormalize(n1graph);
  const n1row = n1.Q[0];
  assert(n1row.length === 5, "Q is nodeCount x nodeCount");
  const n1moviePart = [n1row[1], n1row[2], n1row[3], n1row[4]];
  assert(JSON.stringify(n1moviePart) === "[0,0.5,0.5,0]", "user row over movie nodes = [0,0.5,0.5,0]");
  const n1sum = n1row.reduce(function (a, b) { return a + b; }, 0);
  assert(Math.abs(n1sum - 1) <= 1e-9, "row sum = 1 (|sum-1|<=1e-9)");
  assert(n1.danglingMask[1] === true && n1.danglingMask[4] === true && n1.danglingMask[0] === false && n1.danglingMask[2] === false && n1.danglingMask[3] === false, "danglingMask flags exactly the zero-sum columns");

  console.log("TEST N2: zero row -> no NaN/Infinity, danglingMask set");
  const n2 = rowNormalize({ nodeCount: 2, nUsers: 1, nMovies: 1, R: [[0]] });
  assert(JSON.stringify(n2.Q) === "[[0,0],[0,0]]", "zero row stays all-zero");
  assert(n2.danglingMask[0] === true && n2.danglingMask[1] === true, "both nodes marked dangling");
  const n2syn = rowNormalize(hw6MakeSyntheticGraph([[1, 1, 0], [0, 0, 0]]));
  assert(JSON.stringify(n2syn.danglingMask) === "[false,true,false,false,true]", "starter fixture mask [false,true,false,false,true]");
  let n2finite = true;
  n2syn.Q.forEach(function (row) { row.forEach(function (v) { if (!Number.isFinite(v)) n2finite = false; }); });
  assert(n2finite, "all values finite (no NaN/Infinity)");

  console.log("TEST N3: all non-dangling rows sum to 1 within starter tolerance (1e-9)");
  function checkSums(label, norm) {
    const n = norm.Q.length;
    let bad = 0, nan = 0, neg = 0, checked = 0;
    for (let i = 0; i < n; i++) {
      let s = 0;
      for (let j = 0; j < n; j++) {
        const v = norm.Q[i][j];
        if (!Number.isFinite(v)) nan++;
        if (v < 0) neg++;
        s += v;
      }
      if (!norm.danglingMask[i]) { checked++; if (Math.abs(s - 1) > 1e-9) bad++; }
    }
    assert(bad === 0 && nan === 0 && neg === 0, label + ": " + checked + " non-dangling rows sum to 1, 0 NaN, 0 negative");
  }
  checkSums("synthetic fixture2", n2syn);
  checkSums("N1 fixture", n1);
  const realNorm = evalIn("rowNormalize(getGraph())");
  checkSums("REAL MovieLens graph", realNorm);

  // ================= ITERATION 2: pageRank / PPR =================
  console.log("\n=== REFERENCE CHECKS: pageRank on 4-node fixture ===");
  const refUniform = [0.3725268513, 0.1958239118, 0.3941492369, 0.0375000000];
  const refRestartA = [0.4522328999, 0.1921989825, 0.3555681176, 0.0000000000];

  const prUniform = evalIn(
    "(function(){ var r = pageRank(0.85, {transition: REFERENCE_GRAPH.transition});" +
    " return { p: Array.from(r.p), iterations: r.iterations, residual: r.residual, converged: r.converged, sum: Array.from(r.p).reduce(function(a,b){return a+b;},0) }; })()"
  );
  console.log("PR uniform = " + JSON.stringify(prUniform));
  const prUErr = maxAbs(prUniform.p, refUniform);
  assert(prUErr < 1e-6, "PR1 uniform p matches readme reference (max abs err " + prUErr.toExponential(3) + " < 1e-6)");
  assert(close(prUniform.sum, 1, 1e-9), "PR2 uniform distribution sums to 1 (sum=" + prUniform.sum + ")");
  assert(prUniform.converged === true && prUniform.residual < 1e-6, "PR3 converged=true and residual<1e-6 (" + prUniform.residual.toExponential(3) + ")");
  assert(prUniform.iterations < 500, "PR3b iterations < cap (" + prUniform.iterations + ")");

  const pprA = evalIn(
    "(function(){ var r = personalizedPageRank(0, 0.85, {transition: REFERENCE_GRAPH.transition});" +
    " return { p: Array.from(r.p), iterations: r.iterations, residual: r.residual, converged: r.converged, sum: Array.from(r.p).reduce(function(a,b){return a+b;},0) }; })()"
  );
  console.log("PPR seed A = " + JSON.stringify(pprA));
  const pprAErr = maxAbs(pprA.p, refRestartA);
  assert(pprAErr < 1e-6, "PPR1 restart-at-A p matches readme reference (max abs err " + pprAErr.toExponential(3) + " < 1e-6)");
  assert(close(pprA.sum, 1, 1e-9), "PPR2 one-hot restart distribution sums to 1 (sum=" + pprA.sum + ")");

  const pprB = evalIn(
    "(function(){ var r = personalizedPageRank(1, 0.85, {transition: REFERENCE_GRAPH.transition}); return Array.from(r.p); })()"
  );
  console.log("PPR seed B = " + JSON.stringify(pprB));
  assert(maxAbs(pprA.p, pprB) > 1e-3, "PPR3 different restart nodes give different distributions (seed A vs B)");
  assert(close(sum(pprB), 1, 1e-9), "PPR3b seed B sums to 1");

  const pprLow = evalIn(
    "(function(){ var r = personalizedPageRank(0, 0.50, {transition: REFERENCE_GRAPH.transition}); return Array.from(r.p); })()"
  );
  console.log("PPR seed A alpha=0.50 = " + JSON.stringify(pprLow));
  assert(maxAbs(pprA.p, pprLow) > 1e-3, "PPR4 alpha changes the distribution (0.85 vs 0.50)");

  console.log("\n=== GLOBAL GRAPH pageRank / PPR (raw user id path) ===");
  const globalPR = evalIn(
    "(function(){ var r = pageRank(0.85); return { sum: Array.from(r.p).reduce(function(a,b){return a+b;},0), n: r.p.length, residual: r.residual, converged: r.converged, iterations: r.iterations }; })()"
  );
  console.log("GLOBAL PR = " + JSON.stringify(globalPR));
  assert(globalPR.n === graphInfo.nodeCount, "GLOBAL PR length = nodeCount (" + globalPR.n + ")");
  assert(close(globalPR.sum, 1, 1e-6), "GLOBAL PR sums to ~1 (sum=" + globalPR.sum + ")");
  assert(globalPR.converged === true, "GLOBAL PR converged");

  const rawUserId = evalIn("HW6_STATE.trainUserIds[0]");
  const expectedNode = evalIn("getGraph().nodeOfUser(HW6_STATE.trainUserIds[0])");
  const globalPPR = evalIn(
    "(function(){ var u = HW6_STATE.trainUserIds[0]; var r = personalizedPageRank(u, 0.85);" +
    " return { sum: Array.from(r.p).reduce(function(a,b){return a+b;},0), n: r.p.length, converged: r.converged }; })()"
  );
  console.log("GLOBAL PPR rawUserId=" + rawUserId + " expectedNode=" + expectedNode + " -> " + JSON.stringify(globalPPR));
  assert(globalPPR.n === graphInfo.nodeCount, "GLOBAL PPR length = nodeCount");
  assert(close(globalPPR.sum, 1, 1e-6), "GLOBAL PPR sums to ~1 (raw-user-id mapping)");
  assert(globalPPR.converged === true, "GLOBAL PPR converged");

  console.log("\n=== DANGLING NODE POLICY ===");
  const dangling = evalIn(
    "(function(){ var mask = new Uint8Array([0,0,1]);" +
    " var Q = [[0,1,0],[0,0,1],[0,0,0]];" +
    " var r = pageRank(0.85, {transition: {Q: Q, danglingMask: mask}});" +
    " var s = Array.from(r.p).reduce(function(a,b){return a+b;},0);" +
    " var finite = Array.from(r.p).every(Number.isFinite);" +
    " return { p: Array.from(r.p), sum: s, finite: finite, converged: r.converged }; })()"
  );
  console.log("DANGLING PR = " + JSON.stringify(dangling));
  assert(close(dangling.sum, 1, 1e-6), "D1 dangling mass is redistributed; sum stays 1 (sum=" + dangling.sum + ")");
  assert(dangling.finite === true, "D2 no NaN/Infinity with a dangling node");
  assert(dangling.p[2] > 0.01, "D3 dangling node 2 keeps non-trivial mass (p2=" + dangling.p[2] + ")");

  console.log("\n=== FAILURE CASES ===");
  const e1 = evalIn("(function(){ try { pageRank(1.5, {transition: REFERENCE_GRAPH.transition}); return 'NO_THROW'; } catch(e) { return e.message; } })()");
  assert(String(e1).indexOf("NO_THROW") === -1, "alpha>1 throws (" + e1 + ")");
  const e2 = evalIn("(function(){ try { pageRank(-0.1, {transition: REFERENCE_GRAPH.transition}); return 'NO_THROW'; } catch(e) { return e.message; } })()");
  assert(String(e2).indexOf("NO_THROW") === -1, "alpha<0 throws (" + e2 + ")");
  const e3 = evalIn("(function(){ try { personalizedPageRank(99, 0.85, {transition: REFERENCE_GRAPH.transition}); return 'NO_THROW'; } catch(e) { return e.message; } })()");
  assert(String(e3).indexOf("NO_THROW") === -1, "out-of-range restart on fixture throws (" + e3 + ")");
  const e4 = evalIn("(function(){ try { personalizedPageRank(999999, 0.85); return 'NO_THROW'; } catch(e) { return e.message; } })()");
  assert(String(e4).indexOf("NO_THROW") === -1, "unmappable restart on global graph throws (" + e4 + ")");

  console.log("\n=== MEMORY (tf tensors) ===");
  const memBefore = evalIn("tf.memory().numTensors");
  evalIn("(function(){ for (var i=0;i<5;i++){ pageRank(0.85, {transition: REFERENCE_GRAPH.transition}); } })()");
  evalIn("(function(){ for (var i=0;i<3;i++){ personalizedPageRank(0, 0.85, {transition: REFERENCE_GRAPH.transition}); } })()");
  evalIn("(function(){ for (var i=0;i<2;i++){ pageRank(0.85); } })()");
  const memAfter = evalIn("tf.memory().numTensors");
  console.log("MEMORY numTensors before=" + memBefore + " after=" + memAfter);
  assert(memAfter <= memBefore, "MEM1 tensor count does not grow across repeated calls (before=" + memBefore + " after=" + memAfter + ")");

  console.log("\nTOTAL ASSERT FAILURES: " + failures);
  console.log("HARNESS RUN1: PASS=" + run1.passed + " FAIL=" + run1.failed + " PENDING=" + run1.pending);
  console.log("HARNESS RUN2: PASS=" + run2.passed + " FAIL=" + run2.failed + " PENDING=" + run2.pending);
  process.exitCode = failures > 0 ? 1 : 0;
}

main().catch(function (e) {
  console.error("RUNNER ERROR:", e && e.stack ? e.stack : e);
  process.exitCode = 2;
});

