  *
  * Prefers `getGraph()` when available, then the `GRAPH` global.
  *
  * @returns {Object|null}
  */
 function hw6ActiveGraph() {
   if (typeof getGraph === "function") {
     try {
       const graph = getGraph();
       if (graph) return graph;
     } catch (error) {
       // Fall through to the global below.
     }
   }
