  // exact `pageRank` propagation / stopping rule via its internal `restart` hook.
  const restart = new Float64Array(n);
  restart[seedNode] = 1;
  return pageRank(damping, {
    tol: options.tol,
    maxIter: options.maxIter,
    transition: options.transition,
    restart: restart,
  });
}

