async function graphPropagateBatch(restarts, alpha, opts) {
  const options = opts || {};
  const tol = Number.isFinite(Number(options.tol)) ? Number(options.tol) : 1e-6;
  const maxIter = Number.isFinite(Number(options.maxIter)) ? Number(options.maxIter) : 500;
  const damping = Number(alpha);
  if (!Number.isFinite(damping) || damping < 0 || damping > 1) throw new Error(...);
  if (typeof tf === "undefined") throw ...;
  const list = Array.isArray(restarts) ? restarts : [];
  const B = list.length;
  if (B === 0) return [];

  const cached = graphGetTensors(GRAPH);
  const nUsers = cached.nUsers, nMovies = cached.nMovies, n = cached.n;
  // Validate each restart
  for (let k=0;k<B;k++){ if(!list[k] || list[k].length!==n) throw new Error("graphPropagateBatch: restart "+k+" must be a length-"+n+" distribution"); }

  // Build V [n,B]
  const vData = new Float32Array(n*B);
  for (let k=0;k<B;k++){ const r=list[k]; for(let i=0;i<n;i++) vData[i*B+k]=Number(r[i])||0; }
  const V = tf.tensor2d(vData,[n,B],"float32");
