"use strict";
const fs = require("fs");
const path = require("path");
const vm = require("vm");
const tf = require("C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js");

const ROOT = "C:\\Users\\pc01\\Documents\\RecSys-LLMs";

function makeSandbox() {
  const listeners = {};
  const el = () => ({
    textContent: "", innerHTML: "", className: "", value: "",
    style: {}, classList: { add() {}, remove() {} },
    addEventListener() {}, appendChild() {}, removeChild() {},
    setAttribute() {}, getAttribute() { return null; },
    querySelector() { return null; }, querySelectorAll() { return []; },
    parentNode: null, firstChild: null,
  });
  const documentStub = {
    readyState: "loading",
    getElementById() { return null; },
    createElement() { return el(); },
    createElementNS() { return el(); },
    querySelector() { return null; },
    querySelectorAll() { return []; },
    addEventListener(ev, cb) { listeners[ev] = cb; },
    body: el(),
  };
  const sandbox = {
    tf, document: documentStub,
    window: {}, console,
    setTimeout, clearTimeout, Promise, Date, Math, JSON, Number, Array,
    Float32Array, Float64Array, Int32Array, Uint8Array, Map, Set,
  };
  sandbox.globalThis = sandbox;
  sandbox.window = sandbox;
  return sandbox;
}

function loadInto(sandbox, file) {
  const code = fs.readFileSync(path.join(ROOT, file), "utf8");
  vm.createContext(sandbox);
  vm.runInContext(code, sandbox, { filename: file });
}

async function main() {
  const sandbox = makeSandbox();
  loadInto(sandbox, "week6/graph.js");
  const g = sandbox;

  // Build a small real graph: 3 users, 4 movies, some positives, one zero movie.
  const train = [];
  const add = (u, m, r) => train.push({ userId: u, movieId: m, rating: r, timestamp: 0 });
  add(1, 10, 5); add(1, 11, 4); add(1, 12, 2);
  add(2, 10, 4); add(2, 12, 5); add(2, 13, 4);
  add(3, 11, 5); add(3, 13, 3);
  // movie 14 never rated positively? Actually 14 not in train => not a node.
  const graph = g.buildGraph(train);
  g.setGraph(graph);
  console.log("graph", { nUsers: graph.nUsers, nMovies: graph.nMovies, nodeCount: graph.nodeCount, edges: graph.positiveEdges });

  const alphas = [0.50, 0.70, 0.85, 0.95];
  const users = [1, 2, 3];
  const n = graph.nodeCount;
  const nUsers = graph.nUsers;

  let maxScoreErr = 0, maxSumErr = 0, iterMismatch = 0, convMismatch = 0;
  for (const alpha of alphas) {
    for (const u of users) {
      const seedNode = graph.nodeOfUser(u);
      // scalar via adapter-equivalent: personalizedPageRank(userId, alpha)
      const scalar = g.personalizedPageRank(u, alpha);
      // batched
      const restart = new Float64Array(n); restart[seedNode] = 1;
      const batch = await g.graphPropagateBatch([restart], alpha, {});
      const bp = batch[0];
      let sum = 0;
      for (let i = 0; i < n; i++) {
        maxScoreErr = Math.max(maxScoreErr, Math.abs(scalar.p[i] - bp.p[i]));
        sum += bp.p[i];
        if (bp.p[i] < 0) console.log("NEG", u, alpha, i, bp.p[i]);
      }
      maxSumErr = Math.max(maxSumErr, Math.abs(sum - 1));
      if (scalar.iterations !== bp.iterations) { iterMismatch++; console.log("ITER MISMATCH", u, alpha, scalar.iterations, bp.iterations); }
      if (scalar.converged !== bp.converged) { convMismatch++; console.log("CONV MISMATCH", u, alpha, scalar.converged, bp.converged); }
    }
  }
  console.log("maxScoreErr", maxScoreErr.toExponential(3), "maxSumErr", maxSumErr.toExponential(3), "iterMismatch", iterMismatch, "convMismatch", convMismatch);

  // Multi-column batch equivalence (all three users at once).
  for (const alpha of alphas) {
    const restarts = users.map((u) => { const r = new Float64Array(n); r[graph.nodeOfUser(u)] = 1; return r; });
    const batch = await g.graphPropagateBatch(restarts, alpha, {});
    let err = 0;
    for (let k = 0; k < users.length; k++) {
      const scalar = g.personalizedPageRank(users[k], alpha);
      for (let i = 0; i < n; i++) err = Math.max(err, Math.abs(scalar.p[i] - batch[k].p[i]));
    }
    console.log("multi-column alpha", alpha, "maxErr", err.toExponential(3));
  }

  // Cancellation test.
  let calls = 0;
  try {
    const restarts = users.map((u) => { const r = new Float64Array(n); r[graph.nodeOfUser(u)] = 1; return r; });
    await g.graphPropagateBatch(restarts, 0.85, { shouldCancel: () => { calls++; return calls > 3; }, maxYieldGapMs: 0 });
    console.log("CANCEL FAILED (no throw)");
  } catch (e) {
    console.log("cancel threw:", e.hw6Cancelled === true, e.message);
  }

  console.log("numTensors after", tf.memory().numTensors);
}

main().catch((e) => { console.error(e); process.exit(1); });

