 /* week6/style.css — HW6 graph-based recommendation starter.
    Derived from week5/style.css so the two applications look consistent
    (same fonts, palette, panel and table styling). Adds the SVG graph host,
    legend swatches, alpha readout, a two-column control layout that collapses
    on narrow screens, and a monospace style for export filenames.
    No external fonts, no stylesheet imports, no frameworks. */
 
 :root {
   --bg: #ffffff;
   --surface: #ffffff;
   --inset: #f2f4f7;
   --border: #d5d9e0;
   --text: #1c2128;
   --muted: #5b6472;
   --accent: #0f6e6e;
   --accent-hover: #0b5656;
   --accent-contrast: #ffffff;
   --warning: #7a4b00;
   --warning-bg: #fff5e0;
   --error: #8a1c1c;
   --error-bg: #fdecec;
   --focus: #b4530a;
   --shadow: 0 1px 2px rgba(28, 33, 40, 0.08), 0 4px 12px rgba(28, 33, 40, 0.06);
   --radius: 8px;
 }
 
 *,
 *::before,
 *::after {
   box-sizing: border-box;
 }
 
 html {
   font-size: 16px;
 }
 
 body {
   margin: 0;
   background: var(--bg);
   color: var(--text);
   font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
   font-size: 1rem;
   line-height: 1.55;
 }
 
 h1, h2, h3 {
   line-height: 1.25;
   margin: 0 0 0.5rem;
 }
 
 h1 { font-size: 1.6rem; }
 h2 { font-size: 1.15rem; margin-top: 0; }
 h3 { font-size: 1rem; margin-top: 1.25rem; margin-bottom: 0.4rem; }
 
 p { margin: 0 0 0.75rem; }
 
 code {
   font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
   font-size: 0.9em;
   background: var(--inset);
   padding: 0.05em 0.3em;
   border-radius: 4px;
 }
 
 /* --- layout ------------------------------------------------------------- */
 
 .site-header {
   background: var(--surface);
   border-bottom: 1px solid var(--border);
   padding: 1.5rem 1.25rem 1rem;
 }
 
 .subtitle {
   color: var(--muted);
   margin-bottom: 0.75rem;
   max-width: 68ch;
 }
 
 .note {
   background: var(--inset);
   border-left: 3px solid var(--accent);
   border-radius: 0 6px 6px 0;
   padding: 0.4rem 0.6rem;
   font-size: 0.9rem;
   color: var(--muted);
   margin-bottom: 0;
   max-width: 68ch;
 }
 
 main {
   display: flex;
   flex-direction: column;
   gap: 1.25rem;
   max-width: 900px;
   margin: 0 auto;
   padding: 1.25rem;
 }
 
 .panel {
   background: var(--surface);
   border: 1px solid var(--border);
   border-radius: var(--radius);
   box-shadow: var(--shadow);
   padding: 1rem;
 }
 
 .site-footer {
   border-top: 1px solid var(--border);
   background: var(--surface);
   color: var(--muted);
   font-size: 0.85rem;
   padding: 1rem 1.25rem 1.5rem;
   max-width: 900px;
   margin: 0 auto;
 }
 
 .site-footer p {
   margin: 0 0 0.35rem;
 }
 
 .site-footer p:last-child {
   margin-bottom: 0;
 }
 
 /* --- status ------------------------------------------------------------- */
 
 .status {
   background: var(--inset);
   border-radius: 6px;
   padding: 0.5rem 0.6rem;
   font-size: 0.9rem;
   color: var(--muted);
   min-height: 2.5rem;
   margin: 0;
 }
 
 .status-line {
   background: var(--inset);
   border-radius: 6px;
   padding: 0.5rem 0.6rem;
   font-size: 0.9rem;
   color: var(--muted);
   margin: 0 0 0.5rem;
   font-variant-numeric: tabular-nums;
 }
 
 .error {
   background: var(--error-bg);
   color: var(--error);
   border-radius: 6px;
   padding: 0.5rem 0.6rem;
   font-size: 0.9rem;
 }
 
 .load-error {
   background: var(--warning-bg);
   color: var(--warning);
   margin: 0;
   padding: 0.75rem 1rem;
   border-bottom: 1px solid var(--border);
 }
 
 /* --- controls ----------------------------------------------------------- */
 
 .control-grid {
   display: grid;
   grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
   gap: 0.75rem 1rem;
   margin-bottom: 1rem;
