 .hint {
   color: var(--muted);
   font-size: 0.8rem;
   margin: 0.25rem 0 0;
 }
 
 .button-row {
   display: flex;
   flex-wrap: wrap;
   gap: 0.5rem;
   margin: 0.5rem 0;
 }
 
 /* HW6: two-button pair (alpha sweep / two-user demo); wraps on narrow screens. */
 .button-pair {
   display: flex;
   flex-wrap: wrap;
   gap: 0.5rem;
   min-width: 0;
 }
 
 button {
   font: inherit;
   padding: 0.5rem 0.9rem;
   border: 1px solid var(--accent);
   border-radius: 6px;
   background: var(--accent);
   color: var(--accent-contrast);
   cursor: pointer;
 }
 
 button:hover {
   background: var(--accent-hover);
   border-color: var(--accent-hover);
 }
 
 button.secondary {
   background: var(--surface);
   color: var(--accent);
 }
 
 button.secondary:hover {
   background: var(--inset);
   color: var(--accent-hover);
   border-color: var(--accent-hover);
 }
 
 button:disabled {
   cursor: not-allowed;
   opacity: 0.55;
 }
 
 button:disabled:hover {
   background: var(--surface);
   color: var(--accent);
   border-color: var(--accent);
 }
 
 :focus-visible {
   outline: 3px solid var(--focus);
   outline-offset: 2px;
 }
 
 input:focus-visible,
 select:focus-visible {
   outline: 3px solid var(--focus);
   outline-offset: 1px;
 }
 
 /* --- alpha slider and readout ------------------------------------------ */
 
 .alpha-row {
   display: flex;
   align-items: center;
   gap: 0.6rem;
   min-width: 0;
 }
 
 .alpha-row input[type="range"] {
   flex: 1 1 auto;
   min-width: 0;
 }
 
 .alpha-value {
   flex: 0 0 auto;
   min-width: 3.2rem;
   text-align: right;
   font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
   font-variant-numeric: tabular-nums;
   font-size: 0.9rem;
   background: var(--inset);
   border: 1px solid var(--border);
   border-radius: 6px;
   padding: 0.2rem 0.4rem;
 }
 
