   display: inline-block;
   color: var(--text);
 }
 
 /* --- graph view --------------------------------------------------------- */
 
 .graph-controls {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 0.5rem;
   margin-bottom: 0.6rem;
 }
 
 .graph-view {
   display: block;
