   gap: 0.35rem;
 }
 
 .legend-swatch {
   display: inline-block;
   width: 0.85rem;
   height: 0.85rem;
   border: 1px solid var(--border);
   border-radius: 3px;
   background: var(--inset);
 }
 
 .caption {
   color: var(--muted);
   font-size: 0.85rem;
   margin: 0.5rem 0 0;
 }
 
 /* --- tables, lists and log --------------------------------------------- */
 
 .summary-list {
   display: grid;
   grid-template-columns: max-content minmax(0, 1fr);
   gap: 0.25rem 1rem;
   margin: 0;
 }
 
 .summary-list dt {
   font-weight: 600;
 }
 
