        sweep = await hw6AsyncAlphaSweep(graph, run);
        HW6_STATE.sweep = { epoch: HW6_STATE.graphEpoch, rows: sweep.rows, best: sweep.best, note: sweep.note };
      } else {
        sweep = { rows: [], best: null, note: graph ? "graph propagation is unavailable" : "no graph is built" };
      }
      hw6RenderAlphaSweep(sweep);
      if (run.cancelled) { cancelled = true; throw hw6CancelledError("after validation sweep"); }
      if (options.stages !== "sweep") {
        if (graph && sweep.best === null) {
          hw6SetStatus("Validation sweep did not select an alpha, so the primary comparison was not run (never report a test result selected by a failed sweep).");
          hw6HideProgressAfter(run);
          return;
        }
        const alpha = sweep.best === null ? hw6ReadAlpha() : sweep.best;
        HW6_STATE.selectedAlpha = sweep.best;
        const comparison = await hw6AsyncComparison(graph, alpha, run);
        hw6RenderComparison(comparison);
        hw6RenderConvergence();
        // recall detail for selected method
        ... 
        hw6SetStatus("Evaluation run complete — selected alpha " + (sweep.best===null?"not selected":hw6Fmt(sweep.best,2)) + "; PPR/PageRank evaluated at that alpha.");
      } else {
        hw6SetStatus("Validation sweep complete — selected " + (sweep.best===null?"not selected (unavailable)":"alpha "+hw6Fmt(sweep.best,2)) + ".");
      }
    } else {
      // comparison-only
      ...
    }
  } catch(error) {
    if (hw6IsCancelledError(error)) {
