const fs = require("fs");
const path = require("path");
const vm = require("vm");

const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const TF = "C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js";
const tf = require(TF);

let failures = 0;
function assert(cond, label) {
  if (cond) console.log("  assert ok: " + label);
  else { failures++; console.log("  ASSERT FAIL: " + label); }
}
function close(a, b, tol) { return Math.abs(a - b) <= tol; }
function maxAbs(a, b) { let m = 0; for (let i = 0; i < a.length; i++) m = Math.max(m, Math.abs(a[i] - b[i])); return m; }

function makeElement(id) {
  return {
    id: id, textContent: "", innerHTML: "", value: "0.85", checked: false,
    className: "", disabled: false, style: {}, dataset: {},
    classList: {
      _s: {},
      add: function (c) { this._s[c] = true; },
      remove: function (c) { delete this._s[c]; },
      toggle: function () {}, contains: function (c) { return !!this._s[c]; },
    },
    addEventListener: function () {}, removeEventListener: function () {},
    appendChild: function () {}, removeChild: function () {},
    setAttribute: function () {}, getAttribute: function () { return null; },
    querySelector: function () { return null; }, querySelectorAll: function () { return []; },
    focus: function () {}, click: function () {},
    scrollTop: 0, scrollHeight: 0, options: [], selectedIndex: 0, length: 0,
  };
}
const elements = new Map();
function getEl(id) { if (!elements.has(id)) elements.set(id, makeElement(id)); return elements.get(id); }

const sandbox = {
  console: console, tf: tf,
  setTimeout: setTimeout, clearTimeout: clearTimeout,
  setInterval: setInterval, clearInterval: clearInterval,
  fetch: async function (url) {
    const file = path.join(WEEK6, String(url).split("?")[0]);
    const text = fs.readFileSync(file, "utf8");
    return { ok: true, status: 200, text: async function () { return text; } };
  },
  document: {
    readyState: "loading", getElementById: getEl,
    addEventListener: function () {}, removeEventListener: function () {},
    createElement: function (t) { return makeElement(t); },
    querySelector: function () { return null; }, querySelectorAll: function () { return []; },
    body: makeElement("body"), title: "",
  },
  navigator: { userAgent: "node-vm-runner" },
  performance: { now: function () { return Date.now(); } },
  URL: URL, URLSearchParams: URLSearchParams,
  requestAnimationFrame: function (cb) { return setTimeout(cb, 0); },
  cancelAnimationFrame: clearTimeout,
  Blob: function Blob() {}, FileReader: function FileReader() {},
  atob: function (s) { return Buffer.from(s, "base64").toString("binary"); },
  btoa: function (s) { return Buffer.from(s, "binary").toString("base64"); },
};
const context = vm.createContext(sandbox);
vm.runInContext("window = globalThis; self = globalThis;", context);

function runFile(name) { vm.runInContext(fs.readFileSync(path.join(WEEK6, name), "utf8"), context, { filename: name }); }
function evalIn(expr) { return vm.runInContext(expr, context); }
function evalAsync(expr) { return vm.runInContext("(async () => { return (" + expr + "); })()", context); }
function clearCaches() { evalIn("HW6_STATE.recCache.clear(); HW6_STATE.pprCache.clear(); HW6_STATE.pageRankCache.clear();"); }
function printChecks(label, res) {
  console.log(label + " -> PASS=" + res.passed + " FAIL=" + res.failed + " PENDING=" + res.pending + " TOTAL=" + res.checks.length);
}

async function main() {
  runFile("data.js"); runFile("graph.js"); runFile("script.js");
  console.log("TF VERSION " + evalIn("tf.version.tfjs"));

  await evalIn("loadData()");
  evalIn(
    "(function () { var s = splitByTimestamp();" +
    "  HW6_SPLIT.train = s.train; HW6_SPLIT.val = s.val; HW6_SPLIT.test = s.test;" +
    "  HW6_MAX_MOVIE_ID = movies.reduce(function (m, movie) { return Math.max(m, movie.id); }, 0);" +
    "  hw6BuildSplitIndices(HW6_SPLIT); })()"
  );

  // ================= OFFICIAL HARNESS =================
  const run1 = evalIn("runSelfChecks({ textContent: '' })");
  printChecks("HARNESS RUN 1 (graph not built)", run1);
  evalIn("hw6HandleBuildGraph()");
  const graphInfo = evalIn("(function () { var g = getGraph(); return g ? { nUsers: g.nUsers, nMovies: g.nMovies, nodeCount: g.nodeCount, edges: g.positiveEdges } : null; })()");
  console.log("BUILT GRAPH " + JSON.stringify(graphInfo));
  const run2 = evalIn("runSelfChecks({ textContent: '' })");
  printChecks("HARNESS RUN 2 (graph built)", run2);
  assert(run2.passed === 12 && run2.failed === 0 && run2.pending === 0, "official harness RUN2 = 12 PASS / 0 FAIL / 0 PENDING");

  const cohortTest = evalIn("JSON.stringify(hw6SharedCohort('test'))");
  const cohortTestArr = JSON.parse(cohortTest);
  console.log("COHORT test = " + cohortTestArr.length + ", val = " + evalIn("hw6SharedCohort('val').length"));

  // ================= POPULARITY GOLDEN =================
  console.log("\n=== Golden popularity baseline (unchanged baseline must match) ===");
  clearCaches();
  const pop = evalIn("(function(){ var r = recallAtK('popularity', 10, 'test'); return { recall: r.recall, cohort: r.cohort.length, perUser: r.perUser }; })()");
  console.log(" popularity macro Recall@10 = " + pop.recall + " (expected 0.07602291343770759), cohort=" + pop.cohort);
  assert(close(pop.recall, 0.07602291343770759, 1e-12), "popularity macro Recall@10 matches review golden");
  const u1 = pop.perUser.filter(function (p) { return p.userId === 1; })[0];
  console.log(" user 1: relevant=" + (u1 && u1.relevant) + " hit=" + (u1 && u1.hit));
  assert(u1 && u1.relevant === 19 && u1.hit === 2, "user 1 popularity: 2 hits / 19 relevant");
  const u1recs = evalIn("(function(){ var r = recommendTopK('popularity', 1, 10, 'test'); return r.map(function(x){return x.movieId;}); })()");
  const goldenIds = [100, 258, 286, 300, 288, 318, 313, 302, 357, 483];
  console.log(" user 1 Top-10 = " + JSON.stringify(u1recs));
  assert(JSON.stringify(u1recs) === JSON.stringify(goldenIds), "user 1 Top-10 matches review golden ids");

  // ================= BATCHED vs SCALAR EQUIVALENCE =================
  console.log("\n=== Batched kernel vs scalar pageRank/PPR on real users ===");
  const eq = await evalAsync(
    "(async function(){" +
    "  var graph = getGraph(); var n = graph.nodeCount; var users = hw6SharedCohort('test').slice(0, 6);" +
    "  var alphas = ALPHA_GRID; var maxErr = 0; var iterDiff = 0; var convDiff = 0; var topDiff = 0; var checked = 0;" +
    "  for (var ai=0; ai<alphas.length; ai++){" +
    "    var alpha = alphas[ai];" +
    "    var restarts = users.map(function(u){ var r = new Float64Array(n); r[graph.nodeOfUser(u)] = 1; return r; });" +
    "    var batch = await graphPropagateBatch(restarts, alpha, {});" +
    "    for (var k=0;k<users.length;k++){" +
    "      var scalar = personalizedPageRank(users[k], alpha);" +
    "      for (var i=0;i<n;i++) maxErr = Math.max(maxErr, Math.abs(scalar.p[i] - batch[k].p[i]));" +
    "      if (scalar.iterations !== batch[k].iterations) iterDiff++;" +
    "      if (scalar.converged !== batch[k].converged) convDiff++;" +
    "      checked++;" +
    "    }" +
    "  }" +
    "  return { maxErr: maxErr, iterDiff: iterDiff, convDiff: convDiff, checked: checked };" +
    "})()"
  );
  console.log(" equivalence " + JSON.stringify(eq));
  assert(eq.maxErr < 1e-5, "batched vs scalar max abs score diff " + eq.maxErr.toExponential(3) + " < 1e-5");
  assert(eq.convDiff === 0, "batched vs scalar convergence flags agree (" + eq.checked + " walks)");

  // Per-user Top-10 scored through each path must match.
  console.log("\n=== Compute-path equivalence through recommendTopK (ppr) ===");
  const pathEq = await evalAsync(
    "(async function(){" +
    "  var graph = getGraph(); var n = graph.nodeCount; var users = hw6SharedCohort('test').slice(0, 4);" +
    "  var alpha = ALPHA_GRID[2]; var mismatches = 0; var maxScoreErr = 0; var checked = 0;" +
    "  for (var k=0;k<users.length;k++){" +
    "    // Path A: scalar (clears caches first)" +
    "    HW6_STATE.recCache.clear(); HW6_STATE.pprCache.clear();" +
    "    HW6_STATE.alphaContext = alpha;" +
    "    var recA = recommendTopK('ppr', users[k], 10, 'test');" +
    "    // Path B: batched prefill then cache hit" +
    "    HW6_STATE.recCache.clear(); HW6_STATE.pprCache.clear();" +
    "    var r0 = new Float64Array(n); r0[graph.nodeOfUser(users[k])] = 1;" +
    "    var out = await graphPropagateBatch([r0], alpha, {});" +
    "    hw6StorePprResult(graph, users[k], alpha, out[0]);" +
    "    var recB = recommendTopK('ppr', users[k], 10, 'test');" +
    "    HW6_STATE.alphaContext = null;" +
    "    checked++;" +
    "    var idsA = recA.map(function(x){return x.movieId;}).join(',');" +
    "    var idsB = recB.map(function(x){return x.movieId;}).join(',');" +
    "    if (idsA !== idsB) { mismatches++; console.log('  MISMATCH user ' + users[k] + ' A=' + idsA + ' B=' + idsB); }" +
    "    for (var j=0;j<Math.min(recA.length,recB.length);j++) maxScoreErr = Math.max(maxScoreErr, Math.abs(recA[j].score - recB[j].score));" +
    "  }" +
    "  return { mismatches: mismatches, maxScoreErr: maxScoreErr, checked: checked };" +
    "})()"
  );
  console.log(" pathEq " + JSON.stringify(pathEq));
  assert(pathEq.mismatches === 0, "scalar and batched PPR produce identical Top-10 ids (" + pathEq.checked + " users)");
  assert(pathEq.maxScoreErr < 1e-5, "scalar and batched PPR Top-10 scores agree to " + pathEq.maxScoreErr.toExponential(3));

  // ================= CACHE 1 -> 2 -> 1 =================
  console.log("\n=== Cache reuse 1 -> 2 -> 1 (no recompute) ===");
  clearCaches();
  evalIn("window.__pprCalls = 0; if (!window.__origPPR) window.__origPPR = personalizedPageRank;" +
    "personalizedPageRank = function(){ window.__pprCalls++; return window.__origPPR.apply(null, arguments); };");
  const seq = evalIn("(function(){ var c = hw6SharedCohort('test'); var a = ALPHA_GRID[2];" +
    " HW6_STATE.alphaContext = a;" +
    " recommendTopK('ppr', c[0], 10, 'test'); var n1 = window.__pprCalls;" +
    " recommendTopK('ppr', c[1], 10, 'test'); var n2 = window.__pprCalls;" +
    " recommendTopK('ppr', c[0], 10, 'test'); var n3 = window.__pprCalls;" +
    " HW6_STATE.alphaContext = null;" +
    " return { n1: n1, n2: n2, n3: n3 }; })()");
  evalIn("personalizedPageRank = window.__origPPR;");
  console.log(" ppr scalar calls after user1, user2, user1 = " + JSON.stringify(seq));
  assert(seq.n1 === 1, "first user triggers exactly one PPR walk");
  assert(seq.n2 === 2, "second user triggers one more walk (total 2)");
  assert(seq.n3 === 2, "re-selecting the first user is a cache hit (still 2 walks)");

  // hw6SetAlpha must not wipe caches (the old no-op invalidation bug).
  console.log("\n=== hw6SetAlpha no longer invalidates caches ===");
  clearCaches();
  evalIn("(function(){ var c = hw6SharedCohort('test'); hw6RunPPR(getGraph(), c[0], 0.85); })()");
  const sizeBefore = evalIn("HW6_STATE.pprCache.size");
  evalIn("hw6SetAlpha(0.70); hw6SetAlpha(0.85);");
  const sizeAfter = evalIn("HW6_STATE.pprCache.size");
  console.log(" pprCache size before/after alpha toggle = " + sizeBefore + "/" + sizeAfter);
  assert(sizeBefore === 1 && sizeAfter === 1, "alpha setter keeps still-valid cached walks");

  // ================= SELECTION / ORDERING REGRESSION =================
  console.log("\n=== Selection ordering: sweep alpha drives TEST, not the slider ===");
  evalIn("if (!window.__origAsyncSweep) window.__origAsyncSweep = hw6AsyncAlphaSweep;" +
    "if (!window.__origAsyncComp) window.__origAsyncComp = hw6AsyncComparison;");
  // (a) sweep winner 0.50 while slider is 0.85 -> comparison must run at 0.50
  evalIn("window.__calledAlpha = null; HW6_STATE.sweep = null;" +
    "hw6AsyncAlphaSweep = async function(){ return { rows: [], best: 0.50, note: '' }; };" +
    "hw6AsyncComparison = async function(g, a, r){ window.__calledAlpha = a; return []; };");
  await evalAsync("hw6RunEvaluationAsync({ stages: 'full' })");
  assert(evalIn("window.__calledAlpha") === 0.50, "TEST comparison ran at the SWEEP-selected alpha 0.50 (slider 0.85)");

  // (b) sweep fails to select -> comparison must NOT run
  evalIn("window.__calledAlpha = null; window.__compCalled = false; HW6_STATE.sweep = null;" +
    "hw6AsyncAlphaSweep = async function(){ return { rows: [], best: null, note: 'no selection' }; };" +
    "hw6AsyncComparison = async function(){ window.__compCalled = true; return []; };");
  await evalAsync("hw6RunEvaluationAsync({ stages: 'full' })");
  assert(evalIn("window.__compCalled") === false, "primary comparison is NOT run when the sweep selects no alpha");
  console.log(" status after failed sweep: " + evalIn("document.getElementById('status').textContent"));

  // (c) a completed sweep is reused on repeat Evaluate
  evalIn("hw6AsyncAlphaSweep = window.__origAsyncSweep; hw6AsyncComparison = window.__origAsyncComp;");
  evalIn("window.__sweepCalls = 0; var __realSweep = hw6AsyncAlphaSweep;" +
    "hw6AsyncAlphaSweep = async function(g, r){ window.__sweepCalls++; return { rows: [{alpha:0.85,recall:0.1}], best: 0.85, note: '' }; };" +
    "HW6_STATE.sweep = { epoch: HW6_STATE.graphEpoch, rows: [{alpha:0.85,recall:0.1}], best: 0.85, note: '' };" +
    "hw6AsyncComparison = async function(){ return []; };");
  await evalAsync("hw6RunEvaluationAsync({ stages: 'full' })");
  console.log(" sweep recomputations on repeat Evaluate = " + evalIn("window.__sweepCalls"));
  assert(evalIn("window.__sweepCalls") === 0, "repeat Evaluate reuses the completed validation sweep (0 recomputations)");
  evalIn("hw6AsyncAlphaSweep = window.__origAsyncSweep; hw6AsyncComparison = window.__origAsyncComp; HW6_STATE.sweep = null;");

  // (d) tie-break toward the smaller alpha
  console.log("\n=== Sweep tie-break toward smaller alpha ===");
  evalIn("if (!window.__origRecall) window.__origRecall = recallAtK;" +
    "recallAtK = function(){ return { recall: 0.123, cohort: [], perUser: [], excludedUnseen: 0, excludedNoEligible: 0 }; };");
  const tie = evalIn("hw6RunAlphaSweep()");
  evalIn("recallAtK = window.__origRecall;");
  console.log(" tie best = " + tie.best + " rows=" + tie.rows.map(function (r) { return r.recall; }).join(","));
  assert(tie.best === 0.50, "exact tie across alphas selects the smaller alpha (0.50)");

  // ================= CANCELLATION =================
  console.log("\n=== Cancellation does not present a partial run as final ===");
  evalIn("if (!window.__origAsyncSweep2) window.__origAsyncSweep2 = hw6AsyncAlphaSweep;" +
    "hw6AsyncAlphaSweep = async function(){ throw hw6CancelledError('test cancel'); }; HW6_STATE.sweep = null;" +
    "hw6AsyncComparison = async function(){ window.__cancelComp = true; return []; }; window.__cancelComp = false;");
  await evalAsync("hw6RunEvaluationAsync({ stages: 'full' })");
  const cancelledStatus = evalIn("document.getElementById('status').textContent");
  console.log(" status: " + cancelledStatus);
  assert(/cancel/i.test(cancelledStatus), "status reports the run was cancelled");
  assert(evalIn("window.__cancelComp") === false, "no primary comparison after a cancelled sweep");
  assert(/cancel/i.test(evalIn("document.getElementById('comparison-results').innerHTML")), "comparison panel shows an honest cancelled note");
  evalIn("hw6AsyncAlphaSweep = window.__origAsyncSweep2; hw6AsyncComparison = window.__origAsyncComp;");

  // ================= PROGRESS PANEL =================
  console.log("\n=== Progress panel updates ===");
  evalIn("hw6UpdateProgress({ stage: 'Validation sweep', alpha: 0.70, alphaIndex: 2, alphaTotal: 4, method: 'ppr', processed: 42, total: 100, elapsed: 1500, backend: 'cpu' });");
  const stageText = evalIn("document.getElementById('hw6-progress-stage').textContent");
  const pctText = evalIn("document.getElementById('hw6-progress-pct').textContent");
  const barWidth = evalIn("document.getElementById('hw6-progress-bar').style.width");
  console.log(" stage='" + stageText + "' pct='" + pctText + "' bar='" + barWidth + "'");
  assert(/Validation sweep/.test(stageText) && /2\/4/.test(stageText), "progress shows stage and alpha index i/4");
  assert(/42\/100/.test(pctText), "progress shows processed/total users");
  assert(barWidth === "42.0%", "progress bar width reflects the real fraction (42%)");

  // ================= MEMORY: batch prefill then rebuild =================
  console.log("\n=== Memory: batched prefill then graph rebuild ===");
  clearCaches();
  const memBase = evalIn("tf.memory().numTensors");
  await evalAsync(
    "(async function(){ var g = getGraph(); var n = g.nodeCount; var users = hw6SharedCohort('test').slice(0,8);" +
    " var restarts = users.map(function(u){ var r = new Float64Array(n); r[g.nodeOfUser(u)]=1; return r; });" +
    " var out = await graphPropagateBatch(restarts, 0.85, {}); return out.length; })()"
  );
  const memAfterBatch = evalIn("tf.memory().numTensors");
  evalIn("hw6HandleBuildGraph()");
  const memAfterRebuild = evalIn("tf.memory().numTensors");
  console.log(" numTensors base=" + memBase + " afterBatch=" + memAfterBatch + " afterRebuild=" + memAfterRebuild);
  assert(memAfterBatch <= memBase + 8, "batched prefill frees its working tensors (base " + memBase + " -> " + memAfterBatch + ")");
  assert(memAfterRebuild <= memBase + 8, "graph rebuild disposes the previous tensor cache (" + memAfterRebuild + ")");

  // ================= R1/R5 (cache cleared before monkeypatch) =================
  console.log("\n=== Filtering/tie-break with monkeypatched scorer (cache cleared) ===");
  clearCaches();
  const u0 = evalIn("hw6SharedCohort('test')[0]");
  evalIn("(function(){ if (typeof window.__realSV === 'undefined') window.__realSV = hw6ScoreVector; hw6ScoreVector = function(){ var ids = HW6_STATE.candidateIds; var s = new Float64Array(ids.length); for (var i=0;i<ids.length;i++) s[i]=0; return { movieIds: ids, scores: s, propagation: null }; }; })()");
  const r1 = evalIn("(function(){ var recs = recommendTopK('popularity', " + u0 + ", 10, 'test'); return recs.map(function(r){return r.movieId;}); })()");
  evalIn("hw6ScoreVector = window.__realSV;");
  let ascending = true;
  for (let i = 1; i < r1.length; i++) if (!(r1[i - 1] < r1[i])) ascending = false;
  console.log(" R1 ids " + JSON.stringify(r1));
  assert(r1.length === 10 && ascending, "R1 equal scores -> ascending movieId");

  clearCaches();
  const eligible2 = evalIn(
    "(function(){ var u = " + u0 + "; var ex = hw6ExclusionSet('test', u); var out=[];" +
    " for (var i=0;i<HW6_STATE.candidateIds.length && out.length<2;i++){ var id=HW6_STATE.candidateIds[i]; if(!ex.has(id)) out.push(id); } return out; })()"
  );
  evalIn("(function(){ if (typeof window.__realSV2 === 'undefined') window.__realSV2 = hw6ScoreVector; hw6ScoreVector = function(){ var ids = HW6_STATE.candidateIds; var s = new Float64Array(ids.length);" +
    " for (var i=0;i<ids.length;i++) s[i]=Number.NEGATIVE_INFINITY;" +
    " var keep = [" + eligible2[0] + "," + eligible2[1] + "];" +
