const fs = require("fs");
const path = require("path");
const vm = require("vm");

const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const TF = "C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js";
const tf = require(TF);

let failures = 0;
function assert(cond, label) {
  if (cond) console.log("  assert ok: " + label);
  else { failures++; console.log("  ASSERT FAIL: " + label); }
}
function close(a, b, tol) { return Math.abs(a - b) <= tol; }
function maxAbs(a, b) { let m = 0; for (let i = 0; i < a.length; i++) m = Math.max(m, Math.abs(a[i] - b[i])); return m; }

function makeElement(id) {
  return {
    id: id, textContent: "", innerHTML: "", value: "0.85", checked: false,
    className: "", disabled: false, style: {}, dataset: {},
    classList: { add: function(){}, remove: function(){}, toggle: function(){}, contains: function(){ return false; } },
    addEventListener: function(){}, removeEventListener: function(){},
    appendChild: function(){}, removeChild: function(){},
    setAttribute: function(){}, getAttribute: function(){ return null; },
    querySelector: function(){ return null; }, querySelectorAll: function(){ return []; },
    focus: function(){}, click: function(){},
    scrollTop: 0, scrollHeight: 0, options: [], selectedIndex: 0, length: 0,
  };
}
const elements = new Map();
function getEl(id) { if (!elements.has(id)) elements.set(id, makeElement(id)); return elements.get(id); }

const sandbox = {
  console: console, tf: tf,
  setTimeout: setTimeout, clearTimeout: clearTimeout,
  setInterval: setInterval, clearInterval: clearInterval,
  fetch: async function (url) {
    const file = path.join(WEEK6, String(url).split("?")[0]);
    const text = fs.readFileSync(file, "utf8");
    return { ok: true, status: 200, text: async function () { return text; } };
  },
  document: {
    readyState: "loading", getElementById: getEl,
    addEventListener: function(){}, removeEventListener: function(){},
    createElement: function (t) { return makeElement(t); },
    querySelector: function(){ return null; }, querySelectorAll: function(){ return []; },
    body: makeElement("body"), title: "",
  },
  navigator: { userAgent: "node-vm-runner" },
  performance: { now: function () { return Date.now(); } },
  URL: URL, URLSearchParams: URLSearchParams,
  requestAnimationFrame: function (cb) { return setTimeout(cb, 0); },
  cancelAnimationFrame: clearTimeout,
  Blob: function Blob(){}, FileReader: function FileReader(){},
  atob: function (s) { return Buffer.from(s, "base64").toString("binary"); },
  btoa: function (s) { return Buffer.from(s, "binary").toString("base64"); },
};
const context = vm.createContext(sandbox);
vm.runInContext("window = globalThis; self = globalThis;", context);

function runFile(name) { vm.runInContext(fs.readFileSync(path.join(WEEK6, name), "utf8"), context, { filename: name }); }
function evalIn(expr) { return vm.runInContext(expr, context); }
function printChecks(label, res) {
  console.log(label + " -> PASS=" + res.passed + " FAIL=" + res.failed + " PENDING=" + res.pending + " TOTAL=" + res.checks.length);
  res.checks.forEach(function (c, i) {
    console.log("  " + (i + 1) + ". [" + c.status + "] " + c.name + (c.detail ? " -- " + c.detail : ""));
  });
}

async function main() {
  runFile("data.js"); runFile("graph.js"); runFile("script.js");
  console.log("TF VERSION " + evalIn("tf.version.tfjs"));

  await evalIn("loadData()");
  evalIn(
    "(function () { var s = splitByTimestamp();" +
    "  HW6_SPLIT.train = s.train; HW6_SPLIT.val = s.val; HW6_SPLIT.test = s.test;" +
    "  HW6_MAX_MOVIE_ID = movies.reduce(function (m, movie) { return Math.max(m, movie.id); }, 0);" +
    "  hw6BuildSplitIndices(HW6_SPLIT); })()"
  );

  const run1 = evalIn("runSelfChecks({ textContent: '' })");
  printChecks("HARNESS RUN 1 (graph not built)", run1);

  evalIn("hw6HandleBuildGraph()");
  const graphInfo = evalIn("(function () { var g = getGraph(); return g ? { nUsers: g.nUsers, nMovies: g.nMovies, nodeCount: g.nodeCount } : null; })()");
  console.log("BUILT GRAPH " + JSON.stringify(graphInfo));

  const run2 = evalIn("runSelfChecks({ textContent: '' })");
  printChecks("HARNESS RUN 2 (graph built)", run2);

  const cohortTest = evalIn("JSON.stringify(hw6SharedCohort('test'))");
  const cohortCount = JSON.parse(cohortTest).length;
  console.log("COHORT test = " + cohortCount + ", val = " + evalIn("hw6SharedCohort('val').length"));

  // ================= R6: movieScores excludes user nodes =================
  console.log("\n=== R6 movieScores: no user nodes, mapping, finite ===");
  const g6 = evalIn("(function(){ var g = buildGraph([{userId:1,movieId:100,rating:5,timestamp:1},{userId:1,movieId:200,rating:5,timestamp:2}]); return g; })()");
  const r6 = evalIn(
    "(function(){ var g = buildGraph([{userId:1,movieId:100,rating:5,timestamp:1},{userId:1,movieId:200,rating:5,timestamp:2}]);" +
    " var p = Float64Array.from([0.9,0.7,0.3]);" +
    " var out = movieScores(p, g);" +
    " return { len: out.length, vals: Array.from(out), movieIds: g.movieIds.slice(), nUsers: g.nUsers, nodeCount: g.nodeCount }; })()"
  );
  console.log(" R6 " + JSON.stringify(r6));
  assert(r6.len === r6.movieIds.length && r6.len === 2, "R6 output length = graph.movieIds.length (no padding)");
  assert(r6.vals[0] === 0.7 && r6.vals[1] === 0.3, "R6 movie-node entries returned in movieIds order [" + r6.vals + "]");
  assert(r6.vals.indexOf(0.9) === -1, "R6 user-node score (0.9) absent from movieScores");
  assert(r6.vals.every(Number.isFinite), "R6 all scores finite");
  const det1 = evalIn("JSON.stringify(Array.from(movieScores(Float64Array.from([0.9,0.7,0.3]), (function(){return buildGraph([{userId:1,movieId:100,rating:5,timestamp:1},{userId:1,movieId:200,rating:5,timestamp:2}]);})())))");
  const det2 = evalIn("JSON.stringify(Array.from(movieScores(Float64Array.from([0.9,0.7,0.3]), (function(){return buildGraph([{userId:1,movieId:100,rating:5,timestamp:1},{userId:1,movieId:200,rating:5,timestamp:2}]);})())))");
  assert(det1 === det2, "R6 mapping deterministic across identical calls");

  // ================= R1: tie-break ascending id =================
  console.log("\n=== R1 tie-break: equal scores -> ascending movieId ===");
  evalIn("(function(){ if (typeof window.__realSV === 'undefined') window.__realSV = hw6ScoreVector; hw6ScoreVector = function(){ var ids = HW6_STATE.candidateIds; var s = new Float64Array(ids.length); for (var i=0;i<ids.length;i++) s[i]=0; return { movieIds: ids, scores: s, propagation: null }; }; })()");
  const u0 = evalIn("hw6SharedCohort('test')[0]");
  const r1 = evalIn("(function(){ var recs = recommendTopK('popularity', " + u0 + ", 10, 'test'); return { ids: recs.map(function(r){return r.movieId;}), scores: recs.map(function(r){return r.score;}) }; })()");
  evalIn("hw6ScoreVector = window.__realSV;");
  console.log(" R1 ids " + JSON.stringify(r1.ids));
  let ascending = true;
  for (let i = 1; i < r1.ids.length; i++) if (!(r1.ids[i - 1] < r1.ids[i])) ascending = false;
  assert(r1.ids.length === 10, "R1 returns K=10 equal-score items");
  assert(ascending, "R1 equal scores are ordered by ascending movieId");
  assert(r1.scores.every(function (s) { return s === 0; }), "R1 all equal scores preserved (0)");

  // ================= R2/R3: split-specific filtering =================
  console.log("\n=== R2/R3 exclusion semantics ===");
  const r23 = evalIn(
    "(function(){ var u = " + u0 + ";" +
    " var valEx = hw6ExclusionSet('val', u); var testEx = hw6ExclusionSet('test', u);" +
    " var superset = true; valEx.forEach(function(id){ if(!testEx.has(id)) superset=false; });" +
    " var recsTest = recommendTopK('popularity', u, 10, 'test');" +
    " var recsVal = recommendTopK('popularity', u, 10, 'val');" +
    " function clean(recs, ex){ for(var i=0;i<recs.length;i++){ if(ex.has(recs[i].movieId)) return false; } return true; }" +
    " return { valSize: valEx.size, testSize: testEx.size, superset: superset," +
    "   testClean: clean(recsTest, testEx), valClean: clean(recsVal, valEx)," +
    "   valTrainOnly: (function(){ return valEx.size <= testEx.size; })() }; })()"
  );
  console.log(" R23 " + JSON.stringify(r23));
  assert(r23.superset === true, "R2 test exclusions are a superset of val exclusions (train+val vs train)");
  assert(r23.testClean === true, "R3 no recommended movie is in the test exclusion set (train+val rated)");
  assert(r23.valClean === true, "R2 no recommended movie is in the val exclusion set (train rated)");
  assert(r23.testSize >= r23.valSize, "R2/R3 test exclusion set >= val exclusion set");

  // ================= R4: candidate universe =================
  console.log("\n=== R4 candidate universe (in-pool only) ===");
  const r4 = evalIn(
    "(function(){ var cohort = hw6SharedCohort('test'); var offenders = 0; var checked = 0;" +
    " var methods = ['popularity','pagerank'];" +
    " for (var mi=0; mi<methods.length; mi++){" +
    "   for (var i=0;i<20 && i<cohort.length;i++){" +
    "     var recs = recommendTopK(methods[mi], cohort[i], 10, 'test');" +
    "     for (var r=0;r<recs.length;r++){ checked++; if(!HW6_STATE.candidateSet.has(recs[r].movieId)) offenders++; if(!Number.isFinite(recs[r].score)) offenders++; }" +
    "   } }" +
    " return { offenders: offenders, checked: checked }; })()"
  );
  console.log(" R4 " + JSON.stringify(r4));
  assert(r4.offenders === 0 && r4.checked > 0, "R4 all " + r4.checked + " recommended ids are in the training candidate pool with finite scores");

  // ================= R5: fewer than K -> no padding =================
  console.log("\n=== R5 insufficient candidates (no padding/fake ids) ===");
  const eligible2 = evalIn(
    "(function(){ var u = " + u0 + "; var ex = hw6ExclusionSet('test', u); var out=[];" +
    " for (var i=0;i<HW6_STATE.candidateIds.length && out.length<2;i++){ var id=HW6_STATE.candidateIds[i]; if(!ex.has(id)) out.push(id); } return out; })()"
  );
  evalIn("(function(){ hw6ScoreVector = function(){ var ids = HW6_STATE.candidateIds; var s = new Float64Array(ids.length);" +
    " for (var i=0;i<ids.length;i++) s[i]=Number.NEGATIVE_INFINITY;" +
    " var keep = [" + eligible2[0] + "," + eligible2[1] + "];" +
    " for (var j=0;j<ids.length;j++){ if (keep.indexOf(ids[j])!==-1) s[j]=1; }" +
    " return { movieIds: ids, scores: s, propagation: null }; }; })()");
  const r5 = evalIn("(function(){ var recs = recommendTopK('popularity', " + u0 + ", 10, 'test'); return { len: recs.length, ids: recs.map(function(r){return r.movieId;}) }; })()");
  evalIn("hw6ScoreVector = window.__realSV;");
  console.log(" R5 ids " + JSON.stringify(r5.ids) + " eligible2 " + JSON.stringify(eligible2));
  assert(r5.len === 2 && r5.ids.length === 2, "R5 returns exactly the 2 available items (no padding to 10)");
  assert(r5.ids.indexOf(eligible2[0]) !== -1 && r5.ids.indexOf(eligible2[1]) !== -1, "R5 exactly the 2 eligible finite-scored ids");

  // ================= R7: relevant threshold + R8 empty relevant =================
  console.log("\n=== R7 relevant threshold (>=4) / R8 empty relevant ===");
  const popTest = evalIn("(function(){ var r = recallAtK('popularity', 10, 'test'); return r; })()");
  console.log(" popularity test recall=" + popTest.recall + " cohort=" + popTest.cohort.length + " unseen=" + popTest.excludedUnseen + " noEligible=" + popTest.excludedNoEligible);
  const r7 = evalIn(
    "(function(){ var r = recallAtK('popularity', 10, 'test');" +
    " var grades = HW6_STATE.gradesBySplit.test;" +
    " var mismatch = 0; var checked = 0;" +
    " for (var i=0;i<r.perUser.length;i++){" +
    "   var pu = r.perUser[i]; var ex = hw6ExclusionSet('test', pu.userId); var gm = grades.get(pu.userId);" +
    "   var rel = 0; gm.forEach(function(rating,movieId){ if(rating>=4.0 && HW6_STATE.candidateSet.has(movieId) && !ex.has(movieId)) rel++; });" +
    "   checked++; if (rel !== pu.relevant) mismatch++; }" +
    " return { mismatch: mismatch, checked: checked, cohortSize: r.cohort.length, perUserLen: r.perUser.length }; })()"
  );
  console.log(" R7 " + JSON.stringify(r7));
  assert(r7.mismatch === 0 && r7.checked > 0, "R7 perUser.relevant matches manual count of rating>=4.0, in-pool, not excluded");
  assert(r7.perUserLen === r7.cohortSize, "R7/R8 perUser length equals cohort size (no empty-relevant user included)");

  const r8 = evalIn(
    "(function(){ var r0 = recallAtK('popularity', 0, 'test');" +
    " var rmf = recallAtK('mf', 10, 'test');" +
    " var rEmpty = recallAtK('popularity', 10, 'test');" +
    " return { k0Recall: r0.recall, mfRecall: rmf.recall, mfCohort: rmf.cohort.length, recallFinite: Number.isFinite(rEmpty.recall), anyNaN: rEmpty.perUser.some(function(p){ return !Number.isFinite(p.hit) || !Number.isFinite(p.relevant); }) }; })()"
  );
  console.log(" R8 " + JSON.stringify(r8));
  assert(Number.isFinite(r8.k0Recall) && Number.isFinite(r8.mfRecall), "R8 K=0 and untrained-MF recalls are finite (no divide by zero / NaN)");
  assert(r8.anyNaN === false, "R8 no NaN in perUser hit/relevant");
  assert(r8.recallFinite === true, "R8 recall finite");

  // ================= R9: shared cohort across all four methods =================
  console.log("\n=== R9 shared cohort (all four methods) ===");
  evalIn("(function(){ if (typeof window.__realRec === 'undefined') window.__realRec = recommendTopK; recommendTopK = function(){ return []; }; })()");
  const cPop = evalIn("JSON.stringify(recallAtK('popularity', 10, 'test').cohort)");
  const cPr = evalIn("JSON.stringify(recallAtK('pagerank', 10, 'test').cohort)");
  const cPpr = evalIn("JSON.stringify(recallAtK('ppr', 10, 'test').cohort)");
  const cMf = evalIn("JSON.stringify(recallAtK('mf', 10, 'test').cohort)");
  evalIn("recommendTopK = window.__realRec;");
  const cShared = evalIn("JSON.stringify(hw6SharedCohort('test'))");
  console.log(" R9 pop=" + JSON.parse(cPop).length + " pr=" + JSON.parse(cPr).length + " ppr=" + JSON.parse(cPpr).length + " mf=" + JSON.parse(cMf).length + " shared=" + JSON.parse(cShared).length);
  assert(cPop === cPr && cPr === cPpr && cPpr === cMf, "R9 popularity/PR/PPR/MF report identical cohort arrays");
  assert(cPop === cShared, "R9 recallAtK cohort equals hw6SharedCohort('test') (single source)");

  // ================= FAIR comparison smoke (functional, not final) =================
  console.log("\n=== FAIR comparison plumbing (functional smoke; alpha NOT selected) ===");
  const fair = evalIn(
    "(function(){ var pop = recallAtK('popularity', 10, 'test'); var pr = recallAtK('pagerank', 10, 'test');" +
    " return { popRecall: pop.recall, prRecall: pr.recall, popCohort: pop.cohort.length, prCohort: pr.cohort.length," +
    " sameCohort: JSON.stringify(pop.cohort) === JSON.stringify(pr.cohort)," +
    " popUnseen: pop.excludedUnseen, prUnseen: pr.excludedUnseen, popNoElig: pop.excludedNoEligible, prNoElig: pr.excludedNoEligible }; })()"
  );
  console.log(" FAIR " + JSON.stringify(fair));
  assert(fair.sameCohort === true && fair.popCohort === fair.prCohort, "FAIR popularity and pagerank use the same cohort");
  assert(fair.popUnseen === fair.prUnseen && fair.popNoElig === fair.prNoElig, "FAIR exclusions identical across methods");

  // ================= H: regression of graph layer =================
  console.log("\n=== H regression: pageRank / PPR reference ===");
  const refUniform = [0.3725268513, 0.1958239118, 0.3941492369, 0.0375];
  const refRestartA = [0.4522328999, 0.1921989825, 0.3555681176, 0.0];
  const prU = evalIn("(function(){ var r = pageRank(0.85, {transition: REFERENCE_GRAPH.transition}); return { p: Array.from(r.p), sum: Array.from(r.p).reduce(function(a,b){return a+b;},0) }; })()");
  assert(maxAbs(prU.p, refUniform) < 1e-6, "H PR uniform reference err " + maxAbs(prU.p, refUniform).toExponential(3) + " < 1e-6");
  assert(close(prU.sum, 1, 1e-6), "H PR probability sum ~1 (" + prU.sum + ")");
  const ppA = evalIn("(function(){ var r = personalizedPageRank(0, 0.85, {transition: REFERENCE_GRAPH.transition}); return { p: Array.from(r.p), sum: Array.from(r.p).reduce(function(a,b){return a+b;},0) }; })()");
  assert(maxAbs(ppA.p, refRestartA) < 1e-6, "H PPR restart-A reference err " + maxAbs(ppA.p, refRestartA).toExponential(3) + " < 1e-6");
  assert(close(ppA.sum, 1, 1e-6), "H PPR probability sum ~1 (" + ppA.sum + ")");
  const dang = evalIn("(function(){ var r = pageRank(0.85, {transition: {Q:[[0,1,0],[0,0,1],[0,0,0]], danglingMask:new Uint8Array([0,0,1])}}); return { sum: Array.from(r.p).reduce(function(a,b){return a+b;},0), p2: r.p[2], finite: Array.from(r.p).every(Number.isFinite) }; })()");
  assert(close(dang.sum, 1, 1e-6) && dang.finite, "H dangling fixture preserves mass (sum=" + dang.sum + ")");

  // ================= I: memory =================
  console.log("\n=== I memory (tf tensors) ===");
  const memBefore = evalIn("tf.memory().numTensors");
  // movieScores / recommendTopK popularity / recallAtK popularity: pure JS (NOT APPLICABLE for tf)
  evalIn("(function(){ for (var i=0;i<3;i++){ recommendTopK('popularity', " + u0 + ", 10, 'test'); } })()");
  evalIn("(function(){ for (var i=0;i<2;i++){ recallAtK('popularity', 10, 'test'); } })()");
  const memMid = evalIn("tf.memory().numTensors");
  // pagerank path reuses the cached global propagation (measured once) -> no per-call growth
  evalIn("(function(){ var c = hw6SharedCohort('test'); for (var i=0;i<3;i++){ recommendTopK('pagerank', c[i], 10, 'test'); } })()");
  // ppr path exercises graph.js tensors per distinct user; must return to baseline
  const pprUsers = evalIn("JSON.stringify(hw6SharedCohort('test').slice(0,2))");
  evalIn("(function(){ var c = hw6SharedCohort('test'); for (var i=0;i<2;i++){ recommendTopK('ppr', c[i], 10, 'test'); } })()");
  const memAfter = evalIn("tf.memory().numTensors");
  console.log(" MEMORY numTensors before=" + memBefore + " mid(popularity/recall)=" + memMid + " after=" + memAfter);
  assert(memMid === memBefore, "I1 movieScores/recommendTopK(pop)/recallAtK(pop) create no tensors (pure JS; identical count " + memBefore + " -> " + memMid + ")");
  assert(memAfter <= memBefore, "I2 PR/PPR recommendation paths do not leak tensors (" + memBefore + " -> " + memAfter + ")");

  console.log("\nTOTAL ASSERT FAILURES: " + failures);
  console.log("HARNESS RUN1: PASS=" + run1.passed + " FAIL=" + run1.failed + " PENDING=" + run1.pending);
  console.log("HARNESS RUN2: PASS=" + run2.passed + " FAIL=" + run2.failed + " PENDING=" + run2.pending);
  process.exitCode = failures > 0 ? 1 : 0;
}

main().catch(function (e) { console.error("RUNNER ERROR:", e && e.stack ? e.stack : e); process.exitCode = 2; });

