const vm = require("vm");

const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const TF = "C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js";
const tf = require(TF);

let failures = 0;
function assert(cond, label) {
  if (cond) console.log("  assert ok: " + label);
  else { failures++; console.log("  ASSERT FAIL: " + label); }
}
function ms(t0) { return Number(process.hrtime.bigint() - t0) / 1e6; }

function makeElement(id) {
  return {
    id: id, textContent: "", innerHTML: "", value: "0.85", checked: false,
    className: "", disabled: false, style: {}, dataset: {},
    classList: {
      _s: {}, add: function (c) { this._s[c] = true; }, remove: function (c) { delete this._s[c]; },
      toggle: function () {}, contains: function (c) { return !!this._s[c]; },
    },
    addEventListener: function () {}, removeEventListener: function () {},
    appendChild: function () {}, removeChild: function () {},
    setAttribute: function () {}, getAttribute: function () { return null; },
    querySelector: function () { return null; }, querySelectorAll: function () { return []; },
    focus: function () {}, click: function () {},
    scrollTop: 0, scrollHeight: 0, options: [], selectedIndex: 0, length: 0,
  };
}
const elements = new Map();
function getEl(id) { if (!elements.has(id)) elements.set(id, makeElement(id)); return elements.get(id); }

const sandbox = {
  console: console, tf: tf,
  setTimeout: setTimeout, clearTimeout: clearTimeout,
  setInterval: setInterval, clearInterval: clearInterval,
  fetch: async function (url) {
    const file = path.join(WEEK6, String(url).split("?")[0]);
    const text = fs.readFileSync(file, "utf8");
    return { ok: true, status: 200, text: async function () { return text; } };
  },
  document: {
    readyState: "loading", getElementById: getEl,
    addEventListener: function () {}, removeEventListener: function () {},
    createElement: function (t) { return makeElement(t); },
    querySelector: function () { return null; }, querySelectorAll: function () { return []; },
    body: makeElement("body"), title: "",
  },
  navigator: { userAgent: "node-vm-runner" },
  performance: { now: function () { return Date.now(); } },
  URL: URL, URLSearchParams: URLSearchParams,
  requestAnimationFrame: function (cb) { return setTimeout(cb, 0); },
  cancelAnimationFrame: clearTimeout,
  Blob: function Blob() {}, FileReader: function FileReader() {},
  atob: function (s) { return Buffer.from(s, "base64").toString("binary"); },
  btoa: function (s) { return Buffer.from(s, "binary").toString("base64"); },
};
const context = vm.createContext(sandbox);
vm.runInContext("window = globalThis; self = globalThis;", context);

function runFile(name) { vm.runInContext(fs.readFileSync(path.join(WEEK6, name), "utf8"), context, { filename: name }); }
function evalIn(expr) { return vm.runInContext(expr, context); }
function evalAsync(expr) { return vm.runInContext("(async () => { return (" + expr + "); })()", context); }
function clearCaches() { evalIn("HW6_STATE.recCache.clear(); HW6_STATE.pprCache.clear(); HW6_STATE.pageRankCache.clear();"); }

async function main() {
  runFile("data.js"); runFile("graph.js"); runFile("script.js");
  console.log("TF VERSION " + evalIn("tf.version.tfjs"));

  await evalIn("loadData()");
  evalIn(
    "(function () { var s = splitByTimestamp();" +
    "  HW6_SPLIT.train = s.train; HW6_SPLIT.val = s.val; HW6_SPLIT.test = s.test;" +
    "  HW6_MAX_MOVIE_ID = movies.reduce(function (m, movie) { return Math.max(m, movie.id); }, 0);" +
    "  hw6BuildSplitIndices(HW6_SPLIT); })()"
  );
  evalIn("hw6HandleBuildGraph()");
  console.log("BUILT GRAPH " + evalIn("(function(){var g=getGraph();return JSON.stringify({n:g.nodeCount,edges:g.positiveEdges});})()"));

  // Make the slider differ from any plausible winner, and disable the seed select.
  evalIn("document.getElementById('alpha').value = '0.95'; document.getElementById('seed-user-select').value = 'abc';");

  // ================= BEFORE TIMINGS (synchronous scalar path) =================
  console.log("\n=== BEFORE: synchronous scalar PPR per-walk cost ===");
  const before = await evalAsync(
    "(function(){ var users = hw6SharedCohort('test').slice(0, 8);" +
    "  var t = []; for (var i=0;i<users.length;i++){ var a=performance.now(); personalizedPageRank(users[i], 0.85); t.push(performance.now()-a); }" +
    "  var first = t[0]; var rest = t.slice(1); var avg = rest.reduce(function(s,x){return s+x;},0)/rest.length;" +
    "  return { first: first, avg: avg, all: t }; })()"
  );
  console.log(" scalar walks ms = [" + before.all.map(function (x) { return x.toFixed(1); }).join(", ") + "]");
  console.log(" first=" + before.first.toFixed(1) + " ms  steady avg=" + before.avg.toFixed(1) + " ms/walk");
  const valCount = evalIn("hw6SharedCohort('val').length");
  const testCount = evalIn("hw6SharedCohort('test').length");
  console.log(" estimated OLD full val sweep (4 alphas x " + valCount + " walks) = " + (4 * valCount * before.avg / 1000).toFixed(1) + " s");

  // ================= AFTER TIMINGS (batched path) =================
  console.log("\n=== AFTER: batched prefill cost ===");
  const after = await evalAsync(
    "(async function(){ var g = getGraph(); var n = g.nodeCount;" +
    "  var users = hw6SharedCohort('val');" +
    "  var restarts = users.map(function(u){ var r=new Float64Array(n); r[g.nodeOfUser(u)]=1; return r; });" +
    "  var a=performance.now(); var out=await graphPropagateBatch(restarts, 0.85, {}); var dt=performance.now()-a;" +
    "  return { ms: dt, perUser: dt/users.length, count: out.length, iters: out.map(function(o){return o.iterations;}).reduce(function(s,x){return s+x;},0)/out.length };" +
    "})()"
  );
  console.log(" batched val (" + after.count + " users) = " + after.ms.toFixed(1) + " ms, " + after.perUser.toFixed(2) + " ms/user, avg iters " + after.iters.toFixed(1));
  console.log(" estimated NEW full val sweep (4 alphas, batched) ~ " + (4 * after.ms / 1000).toFixed(1) + " s");
  const speedup = (before.avg / Math.max(after.perUser, 0.001));
  console.log(" per-walk speedup (scalar avg / batched per-user) = " + speedup.toFixed(1) + "x");
  assert(after.count === valCount, "batched prefill covered the full validation cohort (" + after.count + " = " + valCount + ")");

  // ================= GLOBAL PAGERANK EQUIVALENCE =================
  console.log("\n=== Global PageRank batched vs sync ===");
  const prEq = await evalAsync(
    "(async function(){ var g = getGraph(); var n = g.nodeCount;" +
    "  var r = new Float64Array(n); for (var i=0;i<n;i++) r[i]=1/n;" +
    "  var batch = (await graphPropagateBatch([r], 0.85, {}))[0];" +
    "  var sync = pageRank(0.85);" +
    "  var err=0; for (var i=0;i<n;i++) err=Math.max(err, Math.abs(batch.p[i]-sync.p[i]));" +
    "  return { err: err, batchIter: batch.iterations, syncIter: sync.iterations, batchConv: batch.converged, syncConv: sync.converged }; })()"
  );
  console.log(" PR equivalence " + JSON.stringify(prEq));
  assert(prEq.err < 1e-5, "global PageRank batched vs sync max err " + prEq.err.toExponential(3) + " < 1e-5");
  assert(prEq.batchConv === prEq.syncConv, "global PageRank convergence flags agree");

  clearCaches();

  // ================= END-TO-END ENGINE (MF stubbed) =================
  console.log("\n=== End-to-end Evaluate: validation -> selection -> TEST ===");
  evalIn("if (!window.__origMf) window.__origMf = hw6EnsureMfForNeed; hw6EnsureMfForNeed = async function(){ return null; };");
  evalIn("window.__sweepCalls = 0; if (!window.__origAsyncSweep) window.__origAsyncSweep = hw6AsyncAlphaSweep;" +
    "hw6AsyncAlphaSweep = async function(g, r){ window.__sweepCalls++; return await window.__origAsyncSweep(g, r); };");

  // --- first full run ---
  evalIn("HW6_STATE.sweep = null; HW6_STATE.selectedAlpha = null; HW6_STATE.comparisonRows = null; HW6_STATE.alphaSweepRows = null;");
  clearCaches();
  const tRun1 = process.hrtime.bigint();
  await evalAsync("hw6RunEvaluationAsync({ stages: 'full' })");
  const run1ms = ms(tRun1);
  const state1 = evalIn(
    "(function(){ return { best: HW6_STATE.sweep && HW6_STATE.sweep.best," +
    " selectedAlpha: HW6_STATE.selectedAlpha," +
    " sweepRows: (HW6_STATE.alphaSweepRows||[]).map(function(r){return {alpha:r.alpha, recall:r.recall, cohortSize:r.cohortSize};})," +
    " comp: (HW6_STATE.comparisonRows||[]).map(function(r){return {method:r.method, alpha:r.alpha, recall:r.recall, cohortSize:r.cohortSize, conv:r.converged};})," +
    " csv: serializeResults(), ver: serializeVerification() }; })()"
  );
  console.log(" run1 " + run1ms.toFixed(0) + " ms; sweepCalls=" + evalIn("window.__sweepCalls"));
  console.log(" selected alpha = " + state1.best + " (slider was 0.95)");
  console.log(" val sweep rows = " + JSON.stringify(state1.sweepRows));
  console.log(" TEST comparison = " + JSON.stringify(state1.comp));
  assert(state1.best !== null && state1.best !== 0.95, "validation selected an alpha different from the slider (0.95)");
  assert(state1.selectedAlpha === state1.best, "selectedAlpha equals the validation winner");
  const alphaRows = state1.comp.filter(function (r) { return r.alpha !== null; });
  assert(alphaRows.length === 2 && alphaRows.every(function (r) { return r.alpha === state1.best; }),
    "both PageRank and PPR TEST rows ran at the validation-selected alpha " + state1.best);
  assert(state1.comp.every(function (r) { return r.cohortSize === testCount; }), "every TEST row reports cohort size " + testCount);
  assert(state1.sweepRows.every(function (r) { return r.cohortSize === valCount; }), "every val sweep row reports cohort size " + valCount);
  assert(evalIn("window.__sweepCalls") === 1, "first run performed exactly one validation sweep");
  assert(new RegExp(String(state1.best.toFixed(2)).replace(".", "\\.")).test(state1.csv), "results.csv contains the selected alpha " + state1.best.toFixed(2));
  const ver = JSON.parse(state1.ver);
  console.log(" verification.json: passed=" + ver.passed + " failed=" + ver.failed + " pending=" + ver.pending);
  assert(/node|cpu/.test(String(ver.backend)), "verification.json records the actual backend (" + ver.backend + ")");

  // --- repeat full run: sweep reused, no recompute ---
  const tRun2 = process.hrtime.bigint();
  await evalAsync("hw6RunEvaluationAsync({ stages: 'full' })");
  const run2ms = ms(tRun2);
  console.log("\n repeat run " + run2ms.toFixed(0) + " ms; sweepCalls total=" + evalIn("window.__sweepCalls"));
  assert(evalIn("window.__sweepCalls") === 1, "repeat Evaluate reused the completed sweep (still 1 sweep call)");
  console.log(" repeat/first time ratio = " + (run2ms / run1ms).toFixed(2));

  evalIn("hw6EnsureMfForNeed = window.__origMf; hw6AsyncAlphaSweep = window.__origAsyncSweep;");

  // ================= MEMORY: cancel + repeat =================
  console.log("\n=== Memory: cancellation and repeat ===");
  clearCaches();
  const memBase = evalIn("tf.memory().numTensors");
  const cancelRes = await evalAsync(
    "(async function(){ var g=getGraph(); var n=g.nodeCount; var c=hw6SharedCohort('test').slice(0,16);" +
    "  var restarts=c.map(function(u){var r=new Float64Array(n); r[g.nodeOfUser(u)]=1; return r;});" +
    "  try { await graphPropagateBatch(restarts, 0.85, { maxYieldGapMs: 0, shouldCancel: function(){ return true; } }); return { threw:false }; }" +
    "  catch(e){ return { threw:true, cancelled: !!(e&&e.hw6Cancelled), msg: String(e&&e.message) }; } })()"
  );
  const memAfterCancel = evalIn("tf.memory().numTensors");
  console.log(" cancel result " + JSON.stringify(cancelRes) + "; numTensors base=" + memBase + " after=" + memAfterCancel);
  assert(cancelRes.threw && cancelRes.cancelled, "cancellation throws a marked hw6Cancelled error");
  assert(memAfterCancel === memBase, "cancelled batched run frees every tensor it owned (" + memBase + " -> " + memAfterCancel + ")");

  await evalAsync("(async function(){ var g=getGraph(); var n=g.nodeCount; var c=hw6SharedCohort('test').slice(0,16);" +
    " var restarts=c.map(function(u){var r=new Float64Array(n); r[g.nodeOfUser(u)]=1; return r;});" +
    " await graphPropagateBatch(restarts, 0.85, {}); await graphPropagateBatch(restarts, 0.85, {}); })()");
  const memAfterRepeat = evalIn("tf.memory().numTensors");
  console.log(" after two more batched runs numTensors = " + memAfterRepeat);
  assert(memAfterRepeat === memBase, "repeated batched runs do not grow tensor count (" + memAfterRepeat + ")");

  console.log("\nTOTAL ASSERT FAILURES: " + failures);
  process.exitCode = failures > 0 ? 1 : 0;
}

main().catch(function (e) { console.error("RUNNER ERROR:", e && e.stack ? e.stack : e); process.exitCode = 2; });

