const fs = require("fs");
const path = require("path");
const vm = require("vm");
const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const tf = require("C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js");

let failures = 0;
function assert(cond, label) { if (cond) console.log("  assert ok: " + label); else { failures++; console.log("  ASSERT FAIL: " + label); } }
function makeElement(id) { return { id: id, textContent: "", innerHTML: "", value: "0.85", disabled: false, style: {}, classList: { _s: {}, add: function (c) { this._s[c] = true; }, remove: function (c) { delete this._s[c]; }, contains: function (c) { return !!this._s[c]; } }, addEventListener: function () {}, appendChild: function () {}, setAttribute: function () {}, querySelector: function () { return null; }, querySelectorAll: function () { return []; } }; }
const elements = new Map();
function getEl(id) { if (!elements.has(id)) elements.set(id, makeElement(id)); return elements.get(id); }
const sandbox = {
  console: console, tf: tf, setTimeout: setTimeout, clearTimeout: clearTimeout,
  fetch: async function (url) { const t = fs.readFileSync(path.join(WEEK6, String(url).split("?")[0]), "utf8"); return { ok: true, status: 200, text: async function () { return t; } }; },
  document: { readyState: "loading", getElementById: getEl, addEventListener: function () {}, createElement: function () { return makeElement(); }, querySelector: function () { return null; }, querySelectorAll: function () { return []; }, body: makeElement("body") },
  navigator: { userAgent: "node" }, performance: { now: function () { return Date.now(); } },
  URL: URL, URLSearchParams: URLSearchParams, requestAnimationFrame: function (cb) { return setTimeout(cb, 0); }, cancelAnimationFrame: clearTimeout,
};
const context = vm.createContext(sandbox);
vm.runInContext("window=globalThis; self=globalThis;", context);
function runFile(n) { vm.runInContext(fs.readFileSync(path.join(WEEK6, n), "utf8"), context, { filename: n }); }
function evalIn(e) { return vm.runInContext(e, context); }
function evalAsync(e) { return vm.runInContext("(async()=>{return (" + e + ")})()", context); }

async function main() {
  runFile("data.js"); runFile("graph.js"); runFile("script.js");
  await evalIn("loadData()");
  evalIn("(function(){var s=splitByTimestamp(); HW6_SPLIT.train=s.train; HW6_SPLIT.val=s.val; HW6_SPLIT.test=s.test; HW6_MAX_MOVIE_ID=movies.reduce(function(m,mv){return Math.max(m,mv.id);},0); hw6BuildSplitIndices(HW6_SPLIT);})()");
  evalIn("hw6HandleBuildGraph()");

  // ================= per-alpha residual / mass / iterations / convergence / Top-10 =================
  console.log("=== Scalar vs batched across all four alphas ===");
  const eq = await evalAsync(
    "(async function(){ var g=getGraph(); var n=g.nodeCount; var nU=g.nUsers; var users=hw6SharedCohort('test').slice(0,5);" +
    " var out=[];" +
    " for (var ai=0; ai<ALPHA_GRID.length; ai++){" +
    "   var alpha=ALPHA_GRID[ai];" +
    "   var maxScore=0, maxMass=0, maxRes=0, iterDiff=0, convDiff=0, topDiff=0;" +
    "   for (var k=0;k<users.length;k++){" +
    "     var scalar=personalizedPageRank(users[k], alpha);" +
    "     var restart=new Float64Array(n); restart[g.nodeOfUser(users[k])]=1;" +
    "     var batch=(await graphPropagateBatch([restart], alpha, {}))[0];" +
    "     var sSum=0,bSum=0; for (var i=0;i<n;i++){ maxScore=Math.max(maxScore,Math.abs(scalar.p[i]-batch.p[i])); sSum+=scalar.p[i]; bSum+=batch.p[i]; }" +
    "     maxMass=Math.max(maxMass,Math.abs(sSum-bSum)); maxRes=Math.max(maxRes,Math.abs(scalar.residual-batch.residual));" +
    "     if (scalar.iterations!==batch.iterations) iterDiff++;" +
    "     if (scalar.converged!==batch.converged) convDiff++;" +
    "     function top(p){ var idx=[]; for (var i=nU;i<n;i++) idx.push([i-nU,p[i]]); idx.sort(function(a,b){return b[1]-a[1]||a[0]-b[0];}); return idx.slice(0,10).map(function(x){return x[0];}).join(','); }" +
    "     if (top(scalar.p)!==top(batch.p)) topDiff++;" +
    "   }" +
    "   out.push({ alpha:alpha, maxScore:maxScore, maxMass:maxMass, maxRes:maxRes, iterDiff:iterDiff, convDiff:convDiff, topDiff:topDiff, users:users.length });" +
    " } return out; })()"
  );
  eq.forEach(function (r) { console.log("  alpha " + r.alpha.toFixed(2) + " scoreErr=" + r.maxScore.toExponential(2) + " massErr=" + r.maxMass.toExponential(2) + " resErr=" + r.maxRes.toExponential(2) + " iterDiff=" + r.iterDiff + " convDiff=" + r.convDiff + " topDiff=" + r.topDiff); });
  assert(eq.every(function (r) { return r.maxScore < 1e-5; }), "all four alphas: score diff < 1e-5");
  assert(eq.every(function (r) { return r.maxMass < 1e-5; }), "all four alphas: probability mass diff < 1e-5");
  assert(eq.every(function (r) { return r.convDiff === 0; }), "all four alphas: convergence flags agree");
  assert(eq.every(function (r) { return r.topDiff === 0; }), "all four alphas: identical Top-10 movie nodes");
  assert(eq.every(function (r) { return r.iterDiff <= r.users; }), "all four alphas: iteration counts differ by at most a boundary step");

  // ================= hit/relevant equivalence through recallAtK =================
  console.log("\n=== hit/relevant equivalence through recallAtK (reduced cohort) ===");
  evalIn("window.__origCohort = hw6SharedCohort; hw6SharedCohort = function(n){ return window.__origCohort(n).slice(0,6); };");
  const hit = await evalAsync(
    "(async function(){ var g=getGraph(); var n=g.nodeCount; var users=hw6SharedCohort('test'); var res=[];" +
    " for (var ai=0; ai<ALPHA_GRID.length; ai++){" +
    "   var alpha=ALPHA_GRID[ai];" +
    "   HW6_STATE.recCache.clear(); HW6_STATE.pprCache.clear(); HW6_STATE.alphaContext=alpha;" +
    "   var recScalar=recallAtK('ppr',10,'test');" +
    "   HW6_STATE.recCache.clear(); HW6_STATE.pprCache.clear();" +
    "   for (var k=0;k<users.length;k++){ var r=new Float64Array(n); r[g.nodeOfUser(users[k])]=1; var o=(await graphPropagateBatch([r],alpha,{}))[0]; hw6StorePprResult(g, users[k], alpha, o); }" +
    "   var recBatch=recallAtK('ppr',10,'test');" +
    "   HW6_STATE.alphaContext=null;" +
    "   var hitDiff=0; for (var j=0;j<recScalar.perUser.length;j++){ if (recScalar.perUser[j].hit!==recBatch.perUser[j].hit || recScalar.perUser[j].relevant!==recBatch.perUser[j].relevant) hitDiff++; }" +
    "   res.push({ alpha:alpha, recallScalar:recScalar.recall, recallBatch:recBatch.recall, hitDiff:hitDiff });" +
    " } return res; })()"
  );
  evalIn("hw6SharedCohort = window.__origCohort;");
  hit.forEach(function (r) { console.log("  alpha " + r.alpha.toFixed(2) + " recall scalar=" + r.recallScalar.toFixed(6) + " batch=" + r.recallBatch.toFixed(6) + " hitDiff=" + r.hitDiff); });
  assert(hit.every(function (r) { return r.recallScalar === r.recallBatch; }), "recall@10 identical scalar vs batched for all alphas");
  assert(hit.every(function (r) { return r.hitDiff === 0; }), "per-user hit/relevant identical scalar vs batched");

  // ================= cache invalidation on rebuild =================
  console.log("\n=== Graph rebuild invalidates cached walks ===");
  evalIn("HW6_STATE.recCache.clear(); HW6_STATE.pprCache.clear(); HW6_STATE.alphaContext = 0.85;");
  const u0 = evalIn("hw6SharedCohort('test')[0]");
  const idsA = evalIn("recommendTopK('ppr', " + u0 + ", 10, 'test').map(function(r){return r.movieId;}).join(',')");
  const epochA = evalIn("HW6_STATE.graphEpoch");
  const cacheA = evalIn("HW6_STATE.pprCache.size");
  evalIn("hw6HandleBuildGraph()");
  const epochB = evalIn("HW6_STATE.graphEpoch");
  const cacheAfterRebuild = evalIn("HW6_STATE.pprCache.size");
  const idsB = evalIn("recommendTopK('ppr', " + u0 + ", 10, 'test').map(function(r){return r.movieId;}).join(',')");
  evalIn("HW6_STATE.alphaContext = null;");
  console.log(" ids A=" + idsA);
  console.log(" ids B=" + idsB + "  epoch " + epochA + "->" + epochB + "  pprCache(prefill)=" + cacheA + "->(after rebuild)=" + cacheAfterRebuild);
  assert(epochB === epochA + 1, "graph rebuild bumps graphEpoch");
  assert(cacheAfterRebuild === 0, "graph rebuild clears the PPR cache");
  assert(idsA === idsB && idsA.length > 0, "recomputed Top-10 after rebuild matches (same data, new epoch)");

  // ================= recommendations.csv =================
  console.log("\n=== recommendations.csv export ===");
  evalIn("HW6_STATE.recommendationRows = [];");
  evalIn("hw6SharedCohort('test').slice(0,2).forEach(function(u){ var recs = recommendTopK('ppr', u, 10, 'test'); hw6RecordRecommendationRows(u, 'ppr', 0.85, recs); });");
  const recCsv = evalIn("serializeRecommendations()");
  const recLines = recCsv.trim().split(/\r?\n/);
  console.log(" header: " + recLines[0]);
  console.log(" rows: " + (recLines.length - 1) + "; first: " + recLines[1]);
  assert(recLines[0] === "user_id,method,alpha,rank,movie_id,title,genres,score,training_popularity", "recommendations.csv header matches the required columns");
  assert(recLines.length - 1 >= 20, "recommendations.csv contains the 2 users x 10 rows");
  assert(recLines[1].split(",")[0] === String(evalIn("hw6SharedCohort('test')[0]")), "first recommendation row is for the first cohort user");

  console.log("\nTOTAL ASSERT FAILURES: " + failures);
  process.exitCode = failures > 0 ? 1 : 0;
}
main().catch(function (e) { console.error("RUNNER ERROR:", e && e.stack ? e.stack : e); process.exitCode = 2; });

