/**
 * Deterministic 32-bit PRNG (mulberry32). Returns a function producing values
 * in `[0, 1)`.
 *
 * @param {number} seed
 * @returns {() => number}
 */
function hw6Mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

