   if (typeof graphFixturePropagate === "function") {
     try {
       let p = [0.25, 0.25, 0.25, 0.25];
       if (restartName !== "uniform" && typeof graphFixtureRestartVector === "function") {
         p = Array.from(graphFixtureRestartVector(restartName)).map(Number);
