     const source = result.Q[i];
     const row = new Float64Array(n);
     let sum = 0;
     for (let j = 0; j < n; j++) {
       const raw = source && source[j] !== undefined ? Number(source[j]) : 0;
       row[j] = Number.isFinite(raw) ? raw : 0;
       sum += row[j];
     }
     rows[i] = row;
     degrees[i] = mask ? (mask[i] ? 0 : 1) : sum > 0 ? 1 : 0;
