     nUsers: nUsers,
     nMovies: nMovies,
     userIds: userIds,
     movieIds: movieIds,
     userIndexOf: userIndexOf,
     movieIndexOf: movieIndexOf,
     nodeCount: nodeCount,
     nodeOfUser: function (userId) {
       const local = userIndexOf.get(Number(userId));
       return local === undefined ? -1 : local;
     },
     movieOfNode: function (node) {
