/**
 * Pre-fill the PPR cache for a whole cohort at one alpha using the batched
 * engine, reporting progress and honouring cancellation.
 *
 * @param {Object} graph
 * @param {number[]} cohort
 * @param {number} alpha
 * @param {Object} meta `{ stage, alphaIndex, alphaTotal, method }`
 * @param {{cancelled:boolean, startedAt:number}} run
 * @returns {Promise<void>}
 */
async function hw6PrefillPpr(graph, cohort, alpha, meta, run) {
  const n = hw6NodeCount(graph);
  if (!n) return;
  const users = [];
  const restarts = [];
  for (let i = 0; i < cohort.length; i++) {
    const userId = cohort[i];
    const seedNode = hw6UserNodeIndex(graph, userId);
    if (seedNode < 0) continue;
    const restart = new Float64Array(n);
    restart[seedNode] = 1;
    users.push(userId);
    restarts.push(restart);
  }
  const total = restarts.length;
  hw6UpdateProgress({ stage: meta.stage, alpha: alpha, alphaIndex: meta.alphaIndex, alphaTotal: meta.alphaTotal, method: meta.method, processed: 0, total: total, elapsed: Date.now() - run.startedAt, backend: HW6_STATE.backend });
  for (let start = 0; start < total; start += HW6_BATCH_SIZE) {
    if (run.cancelled) throw hw6CancelledError("pre-fill PPR");
    const chunkR = restarts.slice(start, start + HW6_BATCH_SIZE);
    const results = await graphPropagateBatch(chunkR, alpha, {
      tol: HW6_TOLERANCE,
      maxIter: HW6_MAX_ITERATIONS,
      maxYieldGapMs: HW6_YIELD_GAP_MS,
      shouldCancel: function () { return run.cancelled; },
    });
    for (let k = 0; k < results.length; k++) {
      hw6StorePprResult(graph, users[start + k], alpha, results[k]);
    }
    hw6UpdateProgress({ stage: meta.stage, alpha: alpha, alphaIndex: meta.alphaIndex, alphaTotal: meta.alphaTotal, method: meta.method, processed: Math.min(start + chunkR.length, total), total: total, elapsed: Date.now() - run.startedAt, backend: HW6_STATE.backend });
  }
}

