  runFile("data.js"); runFile("graph.js"); runFile("script.js");

  // ---- Fixture: R=[[1],[0]], nUsers=2, nMovies=1, restarts [[1,0,0],[0,1,0]], alpha .85 ----
  const fixture = evalIn(
    "(function(){ var g=buildGraph([{userId:0,movieId:0,rating:5},{userId:1,movieId:0,rating:3}]);" +
    " setGraph(g); return { nUsers:g.nUsers, nMovies:g.nMovies, R:g.R, n0:g.nodeOfUser(0), n1:g.nodeOfUser(1) }; })()"
  );
  console.log("fixture: " + JSON.stringify(fixture));
  assert(fixture.nUsers === 2 && fixture.nMovies === 1, "fixture has nUsers=2, nMovies=1");
  assert(fixture.n0 === 0 && fixture.n1 === 1, "fixture nodeOfUser(0)=0, nodeOfUser(1)=1");

  const call = "graphPropagateBatch([[1,0,0],[0,1,0]], 0.85, {})";
  const memBase = evalIn("tf.memory().numTensors");
  const r1 = await evalAsync("(async()=>{ var r=await " + call + "; return r.map(function(x){return {iterations:x.iterations,converged:x.converged};}); })()");
  const mem1 = evalIn("tf.memory().numTensors");
  const r2 = await evalAsync("(async()=>{ var r=await " + call + "; return r.map(function(x){return {iterations:x.iterations,converged:x.converged};}); })()");
  const mem2 = evalIn("tf.memory().numTensors");
  const r3 = await evalAsync("(async()=>{ var r=await " + call + "; return r.map(function(x){return {iterations:x.iterations,converged:x.converged};}); })()");
  const mem3 = evalIn("tf.memory().numTensors");
  console.log("fixture iterations: " + JSON.stringify(r1.map(function (x) { return x.iterations; })));
  console.log("tensor counts base=" + memBase + " after1=" + mem1 + " after2=" + mem2 + " after3=" + mem3);
  assert(JSON.stringify(r1.map(function (x) { return x.iterations; })) === "[89,1]", "fixture stop iterations are [89,1] (preserved)");
  assert(r1[0].converged && r1[1].converged, "fixture both columns converge");
  assert(mem1 === mem2 && mem2 === mem3, "repeated fixture calls return to the same cache-adjusted tensor baseline");
  assert(mem1 - memBase <= 5, "first call adds only the cached graph tensors (<=5), no per-call leak");

  // ---- Cancellation with mixed stopping times: cancel mid-flight, no leak ----
