  assert(cancErr !== null && cancErr.indexOf("HW6_JOB_CANCELLED") !== -1, "fixture cancellation propagates HW6_JOB_CANCELLED");
  assert(memPostCancel === memPreCancel, "cancellation mid-flight leaks no tensors");

  // ---- Real-data mixed-user equivalence (disclose float32 diffs) ----
  await evalIn("loadData()");
  evalIn("(function(){var s=splitByTimestamp(); HW6_SPLIT.train=s.train; HW6_SPLIT.val=s.val; HW6_SPLIT.test=s.test; HW6_MAX_MOVIE_ID=movies.reduce(function(m,mv){return Math.max(m,mv.id);},0); hw6BuildSplitIndices(HW6_SPLIT);})()");
  evalIn("hw6HandleBuildGraph()");
  const users = [1, 6, 10];
  const mix = await evalAsync(
    "(async function(){ var g=getGraph(); var n=g.nodeCount; var users=" + JSON.stringify(users) + "; var out=[];" +
    " for (var k=0;k<users.length;k++){" +
    "   var scalar=personalizedPageRank(users[k], 0.85);" +
    "   var r=new Float64Array(n); r[g.nodeOfUser(users[k])]=1;" +
    "   var batch=(await graphPropagateBatch([r], 0.85, {}))[0];" +
