    "   out.push({ user:users[k], maxScore:maxScore, massDiff:Math.abs(sSum-bSum), iterDiff:(scalar.iterations-batch.iterations), convDiff:(scalar.converged===batch.converged?0:1) });" +
    " } return out; })()"
  );
  const memPostReal = evalIn("tf.memory().numTensors");
