  mix.forEach(function (r) { console.log("  mixed user " + r.user + " maxScoreErr=" + r.maxScore.toExponential(2) + " massDiff=" + r.massDiff.toExponential(2) + " iterDiff=" + r.iterDiff + " convDiff=" + r.convDiff); });
