```js
async function hw6PrefillPpr(graph, cohort, alpha, meta, run) {
  const n = hw6NodeCount(graph);
  if (!n) return;
  const missing = [];
  const missingRestarts = [];
  const total = cohort.length;
  for (let i = 0; i < cohort.length; i++) {
    const userId = cohort[i];
    if (hw6CachedPpr(graph, userId, alpha)) continue; // reuse existing walk
    const seedNode = hw6UserNodeIndex(graph, userId);
    if (seedNode < 0) continue;
    const restart = new Float64Array(n);
    restart[seedNode] = 1;
    missing.push(userId);
    missingRestarts.push(restart);
  }
  hw6UpdateProgress({... processed: total - missing.length, total: total ...});
  for (let start = 0; start < missingRestarts.length; start += HW6_BATCH_SIZE) {
    if (run.cancelled) throw ...;
    const chunkR = missingRestarts.slice(start, start + HW6_BATCH_SIZE);
    const results = await graphPropagateBatch(chunkR, alpha, {...});
    for (...) hw6StorePprResult(graph, missing[start+k], alpha, results[k]);
    hw6UpdateProgress({... processed: total - missing.length + Math.min(start+chunkR.length, missingRestarts.length) ...});
  }
}
