function hw6StorePageRankResult(graph, alpha, prop) {
  const key = "pr|" + HW6_STATE.graphEpoch + "|" + hw6AlphaKey(alpha);
  const entry = {
    scores: prop.p,
    iterations: prop.iterations,
    residual: prop.residual,
    converged: prop.converged,
    source: "graph.js:batch",
    graph: graph,
    alpha: alpha,
