  *
  * @param {string[]} header
  * @param {Array<Array<*>>} rows
  * @returns {string}
  */
 function hw6CsvDocument(header, rows) {
   const lines = [hw6CsvRow(header)];
   for (let i = 0; i < rows.length; i++) lines.push(hw6CsvRow(rows[i]));
   return lines.join("\r\n") + "\r\n";
