// ---------------- Defect 4 + 7: end-to-end evaluation, snapshot, exports ----------------
console.log("\n[Defect 4/7] end-to-end evaluation builds an immutable snapshot and populates both exports");
await evalAsync("hw6RunEvaluationAsync()");
const d4 = evalIn(`(function(){
  var s = HW6_STATE.completedSnapshot;
  return {
    runState: HW6_STATE.runState,
    hasSnapshot: !!s,
    identity: s ? s.identity : null,
    selectedAlpha: s ? s.selectedAlpha : null,
    comparison: s ? s.comparisonRows.map(function(r){ return { method:r.method, alpha:r.alpha, recall:r.recall, cohortSize:r.cohortSize, meanPop:r.meanPopularity }; }) : [],
    recMethods: s && s.recommendations ? s.recommendations.methods.map(function(m){ return m.method + "@" + m.alpha; }) : null,
    recRowCount: HW6_STATE.recommendationRows.length,
    runSummary: HW6_STATE.lastRunSummary
  };
})()`);
console.log("  runState=" + d4.runState + " snapshot=" + d4.hasSnapshot + " identity=" + d4.identity + " selectedAlpha=" + d4.selectedAlpha);
console.log("  comparison: " + JSON.stringify(d4.comparison));
console.log("  recMethods: " + JSON.stringify(d4.recMethods) + " recRowCount=" + d4.recRowCount);
console.log("  runSummary: " + JSON.stringify(d4.runSummary));
assert(d4.runState === "completed", "evaluation ends in the completed state");
assert(d4.hasSnapshot === true && d4.identity, "a completed snapshot exists with an identity");
assert(d4.comparison.length === 4, "snapshot holds all four methods");
assert(d4.comparison.every(function (r) { return Number.isFinite(r.recall); }), "every comparison method has a finite recall");
assert(d4.recRowCount > 0, "recommendation rows are recorded by Evaluate alone");
assert(d4.recMethods && d4.recMethods.indexOf("ppr@0.85") >= 0 && d4.recMethods.indexOf("ppr@0.5") >= 0, "recommendations include the controlled PPR settings 0.85 and 0.50");
assert(d4.runSummary && d4.runSummary.elapsedMs !== null, "a final run summary was recorded");

