assert(recLines.length > 1, "recommendations.csv has data rows");
["popularity", "pagerank", "ppr", "mf"].forEach(function (m) {
  assert(recCsv.indexOf("," + m + ",") >= 0, "recommendations.csv contains method " + m);
});
assert(recCsv.indexOf(",0.50,") >= 0 && recCsv.indexOf(",0.85,") >= 0, "recommendations.csv contains the 0.50 and 0.85 PPR control rows");

// ---------------- Defect 4: snapshot is immutable w.r.t. live state ----------------
console.log("\n[Defect 4] exports source from the completed snapshot, not live partial state");
const immut = evalIn(`(function(){
  var before = serializeResults().split(/\\r?\\n/).filter(function(l){return l.length>0;}).length;
  // Corrupt/append live state after completion.
