assert(immut.id === d4.identity, "run identity in exports equals the completed snapshot identity");

// ---------------- Defect 4b: a cancelled run keeps the previous snapshot ----------------
console.log("\n[Defect 4b] a cancelled run does not overwrite the previous completed snapshot");
const p2 = evalAsync("hw6RunEvaluationAsync()");
evalIn("if (HW6_STATE.activeRun) HW6_STATE.activeRun.cancelled = true;");
await p2;
const d4b = evalIn(`(function(){ var s=HW6_STATE.completedSnapshot; return { runState:HW6_STATE.runState, identity: s?s.identity:null, hasSnapshot:!!s, exportStatus: hw6ExportRunIdentity().status }; })()`);
console.log("  " + JSON.stringify(d4b) + " (previous identity was " + d4.identity + ")");
