 /**
  * Convert a value into a valid CSV field (RFC 4180 quoting).
  *
  * @param {*} value
  * @returns {string}
  */
 function hw6CsvField(value) {
   if (value === null || value === undefined) return "";
   const text = String(value);
   if (/[",\r\n]/.test(text)) return '"' + text.replace(/"/g, '""') + '"';
   return text;
 }
 
 /**
  * Join one CSV row.
  *
  * @param {Array<*>} values
