runFile('data.js');runFile('graph.js');runFile('script.js');
const out={scope:'Independent synthetic edge-case regression, not final MovieLens metrics'};
out.completeness=evalIn(`({nullRecallAccepted:hw6ComparisonComplete([{method:'mf',recall:null,error:null,note:'MF not trained yet'}]),singleMethodAccepted:hw6ComparisonComplete([{method:'ppr',recall:.1,error:null}]),nullSweepAccepted:hw6SweepComplete({best:.5,rows:[.5,.7,.85,.95].map(alpha=>({alpha,recall:null,error:null}))})})`);
out.guards=evalIn(`(()=>{HW6_STATE.activeRun={cancelled:false};hw6SetRunning(true);const disabled=document.getElementById('run-tests').disabled;const before=GRAPH;hw6HandleRunTests();const result={disabled,graphUnchanged:before===GRAPH,status:document.getElementById('status').textContent};hw6SetRunning(false);return result})()`);
out.recommendationSnapshot=evalIn(`(()=>{HW6_STATE.completedSnapshot={identity:'completed-fixture',recommendations:{users:[1,2],methods:[]}};HW6_STATE.runState='completed';HW6_STATE.recommendationRows=[{userId:1,method:'ppr',alpha:'0.85',rank:1,movieId:100,title:'Original fixture',genres:'Drama',score:.1,trainingPopularity:1}];const before=serializeRecommendations();HW6_STATE.recommendationRows[0].movieId=999;HW6_STATE.recommendationRows[0].title='Post-run mutable fixture';return {before,after:serializeRecommendations()}})()`);
out.progress=await evalIn(`(async()=>{const g={nUsers:2,nMovies:1,nodeCount:3,R:[[1],[1]],userIndexOf:new Map([[1,0],[2,1]])};GRAPH=g;hw6InvalidateCaches();graphPropagateBatch=async(rs,a,opts)=>{opts.onIteration(1,rs.length);globalThis.seenProgress=document.getElementById('hw6-progress-pct').textContent;return rs.map(p=>({p:Float64Array.from(p),iterations:1,residual:0,converged:true}))};HW6_STATE.lastProgressPaint=0;await hw6PrefillPpr(g,[1,2],.5,{stage:'probe'},{cancelled:false,startedAt:Date.now()});return {displayDuringFirstIteration:seenProgress}})()`);
fs.writeFileSync('audit/HW6_REPAIR_EDGE_CASES_2026-10-18.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));
})().catch(e=>{console.error(e);process.exitCode=1});

