function serializeRecommendations() {
  const snapshot = HW6_STATE.completedSnapshot;
  const header = [
    "user_id", "method", "alpha", "rank", "movie_id", "title", "genres",
    "score", "training_popularity", "list_mean_popularity", "run_id", "run_status",
  ];
  let rows;
  if (snapshot && Array.isArray(snapshot.recommendations)) {
    const identity = { id: snapshot.identity || "", status: HW6_STATE.runState };
    rows = snapshot.recommendations.map(function (row) {
      return [
        row.userId,
        row.method,
        row.alpha,
        row.rank,
        row.movieId,
        row.title,
        row.genres,
        row.score,
        row.trainingPopularity,
        row.listMeanPopularity === undefined || row.listMeanPopularity === null ? "" : hw6Fmt(row.listMeanPopularity),
        identity.id,
        identity.status,
      ];
    });
  } else {
    const groupTotals = {};
    HW6_STATE.recommendationRows.forEach(function (row) {
      const key = row.userId + "|" + row.method + "|" + row.alpha;
      if (!groupTotals[key]) groupTotals[key] = { sum: 0, n: 0 };
      groupTotals[key].sum += Number(row.trainingPopularity) || 0;
      groupTotals[key].n += 1;
    });
    const identity = hw6ExportRunIdentity();
    rows = HW6_STATE.recommendationRows.map(function (row) {
      const key = row.userId + "|" + row.method + "|" + row.alpha;
      const group = groupTotals[key];
      const mean = group && group.n ? group.sum / group.n : "";
      return [
        row.userId,
        row.method,
        row.alpha,
        row.rank,
        row.movieId,
        row.title,
        row.genres,
        row.score,
        row.trainingPopularity,
        mean === "" ? "" : hw6Fmt(mean),
        identity.id,
        identity.status,
      ];
    });
  }
  return hw6CsvDocument(header, rows);
}

