const fs = require("fs");
const F = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6\\script.js";
let s = fs.readFileSync(F, "utf8");

function patchBlock(fnName, nextFnName, mut) {
  const start = s.indexOf("function " + fnName);
  const end = s.indexOf("function " + nextFnName, start);
  if (start < 0 || end < 0) { console.log("missing " + fnName); return; }
  let block = s.slice(start, end);
  const nb = mut(block);
  if (nb === block) { console.log("no change " + fnName); return; }
  s = s.slice(0, start) + nb + s.slice(end);
  console.log("patched " + fnName);
}

// 1) hw6ComparisonComplete: raw type/range recall, selected alpha check,
//    cohort required (not optional), sweepBest empty recall check.
patchBlock("hw6ComparisonComplete", "hw6CloneRows", (b) => {
  b = b.replace(
    "    if (!Number.isFinite(Number(r.recall))) return false;",
    "    const recallRaw = r.recall;\n    if (typeof recallRaw !== \"number\" || !Number.isFinite(recallRaw) || recallRaw < 0 || recallRaw > 1) return false;",
  );
  b = b.replace(
    "    if (HW6_STATE.splitReady) {\n      const tcoh = hw6SharedCohort(\"test\");\n      if (Number.isFinite(r.cohortSize) && r.cohortSize !== tcoh.length) return false;\n    }",
    "    if (HW6_STATE.splitReady) {\n      const tcoh = hw6SharedCohort(\"test\");\n      if (typeof r.cohortSize !== \"number\" || !Number.isFinite(r.cohortSize) || r.cohortSize !== tcoh.length) return false;\n    }",
  );
  b = b.replace(
    "    if (m === \"pagerank\" || m === \"ppr\") {\n      if (r.alpha === null || r.alpha === undefined) return false;\n      if (!Number.isFinite(Number(r.alpha))) return false;",
    "    if (m === \"pagerank\" || m === \"ppr\") {\n      if (r.alpha === null || r.alpha === undefined) return false;\n      if (typeof r.alpha !== \"number\" || !Number.isFinite(r.alpha)) return false;\n      if (typeof HW6_STATE.selectedAlpha === \"number\" && HW6_STATE.selectedAlpha !== null && r.alpha !== HW6_STATE.selectedAlpha) return false;",
  );
  return b;
});

// 2) hw6SweepComplete: raw recall type/range, cohort required, best in grid.
patchBlock("hw6SweepComplete", "hw6ComparisonComplete", (b) => {
  b = b.replace(
    "    if (!Number.isFinite(Number(r.recall))) return false;",
    "    const recallRaw = r.recall;\n    if (typeof recallRaw !== \"number\" || !Number.isFinite(recallRaw) || recallRaw < 0 || recallRaw > 1) return false;",
  );
  b = b.replace(
    "    if (HW6_STATE.splitReady) {\n      const vcoh = hw6SharedCohort(\"val\");\n      if (Number.isFinite(r.cohortSize) && r.cohortSize !== vcoh.length) return false;\n    }",
    "    if (HW6_STATE.splitReady) {\n      const vcoh = hw6SharedCohort(\"val\");\n      if (typeof r.cohortSize !== \"number\" || !Number.isFinite(r.cohortSize) || r.cohortSize !== vcoh.length) return false;\n    }",
  );
  return b;
});

// 3) hw6RecordCohortRecommendations returns {users, methods, rows}
patchBlock("hw6RecordCohortRecommendations", "hw6StorePprResult", (b) => {
  if (b.indexOf("rows: hw6CloneRows(HW6_STATE.recommendationRows)") >= 0) return b;
  b = b.replace(
    "  return {\n    users: [userA, userB],\n    methods: summary\n  };",
    "  return {\n    users: [userA, userB],\n    methods: summary,\n    rows: hw6CloneRows(HW6_STATE.recommendationRows),\n  };",
  );
  return b;
});

// 4) serializeRecommendations reads snapshot.recommendations.rows
const ser = "function serializeRecommendations() {";
const i = s.indexOf(ser);
if (i >= 0) {
  const j = s.indexOf("\nfunction ", i + 1);
  let blk = s.slice(i, j);
  if (blk.indexOf("snapshot.recommendations)") < 0 && blk.indexOf("Array.isArray(snapshot.recommendations)") < 0) {
    blk = blk.replace(
      "if (snapshot && Array.isArray(snapshot.recommendations)) {",
      "const snapRecs = snapshot && snapshot.recommendations && Array.isArray(snapshot.recommendations.rows)\n    ? snapshot.recommendations\n    : null;\n  if (snapRecs) {",
    );
    blk = blk.replace("rows = snapshot.recommendations.map(", "rows = snapRecs.rows.map(");
    s = s.slice(0, i) + blk + s.slice(j);
    console.log("patched serializeRecommendations");
  } else {
    console.log("serializeRecommendations already uses array form or different");
  }
} else {
  console.log("serializeRecommendations not found");
}

fs.writeFileSync(F, s);
console.log("wrote");

