 function hw6MovieIds(graph) {
   if (!graph) return [];
   if (Array.isArray(graph.movieIds)) return graph.movieIds;
   if (Array.isArray(graph.nodes)) {
     return graph.nodes
       .filter(function (node) { return node && (node.kind === "movie" || node.type === "movie"); })
