   if (!target) return;
   if (hw6RefuseIfBusy("Recommend Top-10")) return;
   const method = hw6ReadMethod();
   const alpha = hw6ReadAlpha();
   if (method === "mf" && (HW6_MF_MODEL === null || MF_INFO.trainedAt === null)) {
     await hw6EnsureMfForNeed();
