       ", converged " + (verdict.value ? "yes" : "no") + (verdict.derived ? " (derived)" : "") + ".",
     );
   } catch (error) {
     if (target) target.innerHTML = hw6UnavailableHtml("Convergence", error);
     hw6SetStatus("PageRank unavailable: " + String(error && error.message ? error.message : error));
   }
 }
 
