const fs = require("fs");
const path = require("path");
const vm = require("vm");
const WEEK6 = "C:/Users/pc01/Documents/RecSys-LLMs/week6";
const tf = require("C:/Users/pc01/AppData/Local/Temp/opencode/tf.min.js");
function el(id) {
  return { id, textContent: "", innerHTML: "", value: "0.85", checked: false, className: "", disabled: false, style: {}, dataset: {},
    classList: { _s: {}, add() {}, remove() {}, toggle() {}, contains() { return false; } },
    addEventListener() {}, removeEventListener() {}, appendChild() {}, removeChild() {}, setAttribute() {}, getAttribute() { return null; },
    querySelector() { return null; }, querySelectorAll() { return []; }, focus() {}, click() {}, scrollTop: 0, scrollHeight: 0, options: [], selectedIndex: 0, length: 0 };
}
const els = new Map();
const sandbox = {
  console, tf, setTimeout, clearTimeout, setInterval, clearInterval,
  fetch: async (u) => ({ ok: true, status: 200, text: async () => fs.readFileSync(path.join(WEEK6, String(u).split("?")[0]), "utf8") }),
  document: { readyState: "loading", getElementById: (id) => { if (!els.has(id)) els.set(id, el(id)); return els.get(id); },
    addEventListener() {}, removeEventListener() {}, createElement: (t) => el(t), querySelector() { return null; }, querySelectorAll() { return []; }, body: el("body"), title: "" },
  navigator: { userAgent: "node" }, performance: { now: Date.now }, URL, URLSearchParams,
  requestAnimationFrame: (cb) => setTimeout(cb, 0), cancelAnimationFrame: clearTimeout,
  Blob: function () {}, FileReader: function () {}, atob: (s) => Buffer.from(s, "base64").toString("binary"), btoa: (s) => Buffer.from(s, "binary").toString("base64"),
};
const ctx = vm.createContext(sandbox);
vm.runInContext("window=globalThis;self=globalThis;", ctx);
["data.js", "graph.js", "script.js"].forEach((f) => vm.runInContext(fs.readFileSync(path.join(WEEK6, f), "utf8"), ctx, { filename: f }));
const ev = (e) => vm.runInContext(e, ctx);
ev("HW6_STATE.splitReady=true; hw6SharedCohort=(s)=>s==='val'?[1,2]:[1,2,3]; HW6_STATE.selectedAlpha=0.5;");

const base = (rec) => "['popularity','pagerank','ppr','mf'].map(m=>({method:m,recall:" + rec + ",split:'test',cohortSize:3,alpha:(m==='pagerank'||m==='ppr')?0.5:null,error:null}))";
const out = {};
out.validAccepted = ev("hw6ComparisonComplete(" + base(0.1) + ")");
out.zeroRecallAccepted = ev("hw6ComparisonComplete(" + base(0) + ")");
out.oneRecallAccepted = ev("hw6ComparisonComplete(" + base(1) + ")");
out.undefinedRecallAccepted = ev("(()=>{const r=" + base(0.1) + ";r[3].recall=undefined;return hw6ComparisonComplete(r)})()");
out.nanRecallAccepted = ev("(()=>{const r=" + base(0.1) + ";r[3].recall=NaN;return hw6ComparisonComplete(r)})()");
out.infinityRecallAccepted = ev("(()=>{const r=" + base(0.1) + ";r[3].recall=Infinity;return hw6ComparisonComplete(r)})()");
out.stringRecallAccepted = ev("(()=>{const r=" + base(0.1) + ";r[3].recall='0.5';return hw6ComparisonComplete(r)})()");
out.duplicateMethodAccepted = ev("(()=>{const r=" + base(0.1) + ";r[3].method='ppr';return hw6ComparisonComplete(r)})()");
out.wrongSplitAccepted = ev("(()=>{const r=" + base(0.1) + ";r[0].split='val';return hw6ComparisonComplete(r)})()");
out.errorRowAccepted = ev("(()=>{const r=" + base(0.1) + ";r[0].error='boom';return hw6ComparisonComplete(r)})()");
out.wrongCohortAccepted = ev("(()=>{const r=" + base(0.1) + ";r[2].cohortSize=99;return hw6ComparisonComplete(r)})()");
out.unavailableMfAccepted = ev("(()=>{const r=" + base(0.1) + ";r[3].recall=null;return hw6ComparisonComplete(r)})()");

out.zeroSweepAccepted = ev("hw6SweepComplete({best:0,rows:[0.5,0.7,0.85,0.95].map(a=>({alpha:a,recall:0,cohortSize:2}))})");
out.argmaxSweepAccepted = ev("hw6SweepComplete({best:0.5,rows:[{alpha:0.5,recall:0.9,cohortSize:2},{alpha:0.7,recall:0.1,cohortSize:2},{alpha:0.85,recall:0.2,cohortSize:2},{alpha:0.95,recall:0.1,cohortSize:2}]})");
out.bestNotArgmaxAccepted = ev("hw6SweepComplete({best:0.95,rows:[{alpha:0.5,recall:0.9,cohortSize:2},{alpha:0.7,recall:0.1,cohortSize:2},{alpha:0.85,recall:0.2,cohortSize:2},{alpha:0.95,recall:0.1,cohortSize:2}]})");
out.duplicateGridAlphaAccepted = ev("hw6SweepComplete({best:0.5,rows:[{alpha:0.5,recall:0.5,cohortSize:2},{alpha:0.5,recall:0.4,cohortSize:2},{alpha:0.85,recall:0.1,cohortSize:2},{alpha:0.95,recall:0.1,cohortSize:2}]})");
out.outOfGridAlphaAccepted = ev("hw6SweepComplete({best:0.5,rows:[{alpha:0.5,recall:0.5,cohortSize:2},{alpha:0.6,recall:0.4,cohortSize:2},{alpha:0.85,recall:0.1,cohortSize:2},{alpha:0.95,recall:0.1,cohortSize:2}]})");

// snapshot export isolation: cancel a later run, mutate live rows, slider change
out.snapshotIsolation = ev(`(()=>{
  hw6SharedCohort=()=>[1,2];
  recommendTopK=(m,u,k,s)=>Array.from({length:k},(_,i)=>({movieId:i+1,title:'Synthetic '+(i+1),genres:['Drama'],score:1/(i+1),popularity:2}));
  hw6ResetRecommendationRows();
  const recs=hw6RecordCohortRecommendations(0.5);
  HW6_STATE.completedSnapshot=hw6BuildCompletedSnapshot({identity:'iso-run',alpha:0.5,selectedAlpha:0.5,comparisonRows:[],alphaSweepRows:[],convergence:{},recommendations:recs,config:{}});
  HW6_STATE.runState='completed';
  const before=serializeRecommendations();
  HW6_STATE.recommendationRows[0].title='MUTATED';
  HW6_STATE.recommendationRows.push({userId:2,method:'mf',alpha:'',rank:1,movieId:777,title:'EXTRA',genres:'',score:.5,trainingPopularity:1});
  HW6_STATE.selectedAlpha=0.95;
  HW6_STATE.runState='cancelled';
  const after=serializeRecommendations();
  return {rowsInSnapshot:recs.rows.length,unchanged:before===after,mutationInExport:after.includes('MUTATED'),extraInExport:after.includes('EXTRA'),runStatus:after.split('\\r\\n')[1].split(',').slice(-1)[0]};
})()`);

fs.writeFileSync("C:/Users/pc01/Documents/RecSys-LLMs/audit/HW6_CONTRACT_FIX_EXTRA_PROBES_2026-10-18.json", JSON.stringify(out, null, 2));
console.log(JSON.stringify(out, null, 2));

