// HW6 MF diagnostic runner (test-only, production code untouched).
// Variant A: exactly the shipped hw6TrainMf (full L2 sum).
// Variant B: identical source except the L2 term is scaled by reg / batchSize.
// Everything else (data, split, seed, HP, checkpoint rule, scorer) is shared.
const fs = require("fs");
const path = require("path");
const vm = require("vm");
const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const tf = require("C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js");

function makeElement(id) {
  return { id: id, textContent: "", innerHTML: "", value: "0.85", disabled: false, style: {},
    classList: { _s: {}, add: function (c) { this._s[c] = true; }, remove: function (c) { delete this._s[c]; }, contains: function (c) { return !!this._s[c]; } },
    addEventListener: function () {}, appendChild: function () {}, setAttribute: function () {},
    querySelector: function () { return null; }, querySelectorAll: function () { return []; } };
}
const els = new Map(); function getEl(id) { if (!els.has(id)) els.set(id, makeElement(id)); return els.get(id); }

function makeContext(scriptSource) {
  const sandbox = {
    console: console, tf: tf, setTimeout: setTimeout, clearTimeout: clearTimeout,
    fetch: async function (url) { const t = fs.readFileSync(path.join(WEEK6, String(url).split("?")[0]), "utf8"); return { ok: true, status: 200, text: async function () { return t; } }; },
    document: { readyState: "loading", getElementById: getEl, addEventListener: function () {}, createElement: function () { return makeElement(); }, querySelector: function () { return null; }, querySelectorAll: function () { return []; }, body: makeElement("body") },
    navigator: { userAgent: "node" }, performance: { now: function () { return Date.now(); } },
    URL: URL, URLSearchParams: URLSearchParams,
    requestAnimationFrame: function (cb) { return setTimeout(cb, 0); }, cancelAnimationFrame: clearTimeout,
  };
  const context = vm.createContext(sandbox);
  vm.runInContext("window=globalThis; self=globalThis;", context);
  vm.runInContext(fs.readFileSync(path.join(WEEK6, "data.js"), "utf8"), context, { filename: "data.js" });
  vm.runInContext(fs.readFileSync(path.join(WEEK6, "graph.js"), "utf8"), context, { filename: "graph.js" });
  vm.runInContext(scriptSource, context, { filename: "script.js" });
  return context;
}
function ev(ctx, code) { return vm.runInContext(code, ctx); }
function eva(ctx, code) { return vm.runInContext("(async()=>{ return (" + code + "); })()", ctx); }

const shipped = fs.readFileSync(path.join(WEEK6, "script.js"), "utf8");
const L2_LINE = "const l2 = userFactors.square().sum().add(itemFactors.square().sum()).mul(MF_CONFIG.reg);";
if (shipped.split(L2_LINE).length !== 2) { console.error("FATAL: L2 line not uniquely found in shipped script.js"); process.exit(2); }
const variantBSource = shipped.replace(L2_LINE, "const l2 = userFactors.square().sum().add(itemFactors.square().sum()).mul(MF_CONFIG.reg / size);");
if (variantBSource === shipped) { console.error("FATAL: variant B substitution did nothing"); process.exit(2); }

// ---- plain-JS data prep (mirrors week6/data.js splitByTimestamp) ----
function loadSplit() {
  const text = fs.readFileSync(path.join(WEEK6, "u.data"), "utf8");
  const ratings = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const f = line.split("\t");
    if (f.length < 4) continue;
    ratings.push({ userId: parseInt(f[0]), movieId: parseInt(f[1]), rating: parseFloat(f[2]), timestamp: parseInt(f[3]) });
  }
  const byUser = new Map();
  for (const r of ratings) { if (!byUser.has(r.userId)) byUser.set(r.userId, []); byUser.get(r.userId).push(r); }
  const train = [], val = [], test = [];
  for (const [, list] of byUser) {
    const n = list.length;
    if (n < 5) continue;
    const sorted = list.slice().sort((a, b) => a.timestamp - b.timestamp || a.movieId - b.movieId);
    const nTrain = Math.floor(0.8 * n), nVal = Math.floor(0.1 * n);
    for (let i = 0; i < n; i++) (i < nTrain ? train : i < nTrain + nVal ? val : test).push(sorted[i]);
  }
  return { train: train, val: val, test: test };
}
function rmseConstant(split, c) {
  let s = 0;
  for (const r of split) { const d = r.rating - c; s += d * d; }
  return Math.sqrt(s / split.length);
}

function stats(values) {
  let min = Infinity, max = -Infinity, sum = 0;
  for (const v of values) { if (v < min) min = v; if (v > max) max = v; sum += v; }
  const mean = sum / values.length;
  let sq = 0; for (const v of values) sq += (v - mean) * (v - mean);
  const sd = Math.sqrt(sq / values.length);
  const uniq64 = new Set(values.map(function (v) { return v; })).size;
  const uniq32 = new Set(values.map(function (v) { return Math.fround(v); })).size;
  return { n: values.length, min: min, max: max, mean: mean, std: sd, unique64: uniq64, uniqueFloat32: uniq32,
    spread_over_std: (max - min) / (sd || 1e-12) };
}

async function runVariant(name, source) {
  console.log("=== " + name + " ===");
  const ctx = makeContext(source);
  const t0 = Date.now();
  await eva(ctx, "hw6InitTf()");
  await eva(ctx, "loadData()");
  ev(ctx, "(function(){ var s = splitByTimestamp(); HW6_SPLIT.train = s.train; HW6_SPLIT.val = s.val; HW6_SPLIT.test = s.test;" +
       " HW6_MAX_MOVIE_ID = movies.reduce(function(m,x){ return Math.max(m, x.id); }, 0); hw6BuildSplitIndices(HW6_SPLIT); return true; })()");
  const setup = ev(ctx, "({ users: numUsers, maxMovieId: HW6_MAX_MOVIE_ID, candidates: HW6_STATE.candidateIds.length, train: HW6_SPLIT.train.length, val: HW6_SPLIT.val.length, test: HW6_SPLIT.test.length })");
  console.log("setup: " + JSON.stringify(setup));

  const trainMean = ev(ctx, "(function(){ var s=0; var t=HW6_SPLIT.train; for (var i=0;i<t.length;i++) s+=t[i].rating; return s/t.length; })()");
  const constant = { trainMean: trainMean, trainMeanFloat32: Math.fround(trainMean),
    rmse_train: rmseConstant(loadSplit().train, trainMean),
    rmse_val: rmseConstant(loadSplit().val, trainMean),
    rmse_test: rmseConstant(loadSplit().test, trainMean) };
  console.log("constant-mean baseline: " + JSON.stringify(constant));

  const t1 = Date.now();
  const model = await eva(ctx, "hw6TrainMf(HW6_SPLIT.train, null)");
  const trainMs = Date.now() - t1;
  const info = ev(ctx, "JSON.parse(JSON.stringify(MF_INFO))");
  console.log("training ms=" + trainMs + " checkpoint=" + info.checkpoint + " valRMSE=" + info.validationRMSE);

  const norms = ev(ctx, "(function(){ var m = HW6_MF_MODEL;" +
    " var u = m.userFactors.dataSync(), it = m.itemFactors.dataSync();" +
    " function fro(a){ var s=0; for (var i=0;i<a.length;i++) s+=a[i]*a[i]; return Math.sqrt(s); }" +
    " function rowNorms(a, rows, cols){ var out=[]; for (var r=0;r<rows;r++){ var s=0; for (var c=0;c<cols;c++){ var v=a[r*cols+c]; s+=v*v; } out.push(Math.sqrt(s)); } return out; }" +
    " var un = rowNorms(u, m.userFactors.shape[0], m.userFactors.shape[1]);" +
    " var inn = rowNorms(it, m.itemFactors.shape[0], m.itemFactors.shape[1]);" +
    " function mm(a){ var s=0; for (var i=0;i<a.length;i++) s+=a[i]; return s/a.length; }" +
    " function mx(a){ var x=-Infinity; for (var i=0;i<a.length;i++) if (a[i]>x) x=a[i]; return x; }" +
    " function mn(a){ var x=Infinity; for (var i=0;i<a.length;i++) if (a[i]<x) x=a[i]; return x; }" +
    " return { userFro: fro(u), itemFro: fro(it), userRowMeanNorm: mm(un), userRowMaxNorm: mx(un), userRowMinNorm: mn(un)," +
    "          itemRowMeanNorm: mm(inn), itemRowMaxNorm: mx(inn), itemRowMinNorm: mn(inn), globalMean: m.globalMean }; })()");

  const scorer = {};
  for (const uid of [1, 2]) {
    const scoresObj = ev(ctx, "mfScores(" + uid + ")");
    const pairs = Object.keys(scoresObj).map(function (k) { return { id: Number(k), s: scoresObj[k] }; });
    pairs.sort(function (a, b) { return a.id - b.id; });
    const vals = pairs.map(function (p) { return p.s; });
    const st = stats(vals);
    // Dot product = score - globalMean (float32 arithmetic as in the page).
    const dots = vals.map(function (v) { return v - Math.fround(norms.globalMean); });
    const eqMean = vals.filter(function (v) { return v === Math.fround(norms.globalMean); }).length;
    scorer[uid] = { scores: st, dots: dots.map(function (d) { return stats([d]); })[0],
      dotsMin: Math.min.apply(null, dots), dotsMax: Math.max.apply(null, dots),
      nExactlyGlobalMean: eqMean, nCandidates: vals.length,
      top10_byScoreDesc: pairs.slice().sort(function (a, b) { return b.s - a.s || a.id - b.id; }).slice(0, 10).map(function (p) { return p.id; }),
      first10_byId: pairs.slice(0, 10).map(function (p) { return p.id; }) };
    scorer[uid].dots = { min: Math.min.apply(null, dots), max: Math.max.apply(null, dots) };
  }

  // Checkpoint restoration check: RMSE of the restored variables must equal bestVal.
  const restoredVal = ev(ctx, "hw6MfRmse(HW6_SPLIT.val)");
  const restoredTrain = ev(ctx, "hw6MfRmse(HW6_SPLIT.train)");
  const bestFromHistory = Math.min.apply(null, info.history.map(function (h) { return h.valRMSE; }));
  const bestEpochFromHistory = info.history.reduce(function (a, h, i) { return h.valRMSE < a.v ? { v: h.valRMSE, e: h.epoch } : a; }, { v: Infinity, e: 0 }).e;
  const history = info.history.map(function (h) { return { epoch: h.epoch, train: Number(h.trainRMSE.toFixed(6)), val: Number(h.valRMSE.toFixed(6)) }; });
  const summary = {
    variant: name,
    l2Term: name === "A_shipped_full_L2" ? "sum(u^2+i^2)*reg" : "sum(u^2+i^2)*(reg/size)",
    setup: setup, trainMs: trainMs,
    hyper: { factors: info.factors, epochs: info.epochs, lr: info.learningRate, reg: info.regularization, batchSize: info.batchSize, seed: info.seed, backend: info.backend },
    constantMeanBaseline: constant,
    history: history,
    checkpoint: { epoch: info.checkpoint, valRMSE: info.validationRMSE,
      restoredValRMSE: restoredVal, restoredTrainRMSE: restoredTrain,
      bestValFromHistory: bestFromHistory, bestEpochFromHistory: bestEpochFromHistory,
      restoredMatchesBest: Math.abs(restoredVal - bestFromHistory) < 1e-6 },
    factorNorms: norms,
    scorer: scorer
  };
  ctx.__summary = summary;
  return { summary: summary, ctx: ctx, setup: setup };
}

async function main() {
  const report = { generated_at: new Date().toISOString(), scope: "Node CPU TF.js diagnostic; not a browser WebGL run",
    tfVersion: tf.version, note: "production week6/script.js not modified; variant B source substituted in memory only" };
  const a = await runVariant("A_shipped_full_L2", shipped);
  report.A = a.summary;
  const b = await runVariant("B_l2_over_batch", variantBSource);
  report.B = b.summary;
  const out = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\audit\\HW6_MF_DIAGNOSTIC_2026-10-19.json";
  fs.writeFileSync(out, JSON.stringify(report, null, 2));
  console.log("WROTE " + out);
  console.log("A checkpoint " + report.A.checkpoint.epoch + " val " + report.A.checkpoint.valRMSE +
    " restored " + report.A.checkpoint.restoredValRMSE + " restoredMatchesBest=" + report.A.checkpoint.restoredMatchesBest);
  console.log("B checkpoint " + report.B.checkpoint.epoch + " val " + report.B.checkpoint.valRMSE +
    " restored " + report.B.checkpoint.restoredValRMSE + " restoredMatchesBest=" + report.B.checkpoint.restoredMatchesBest);
  console.log("A unique scores u1=" + report.A.scorer[1].scores.uniqueFloat32 + " u2=" + report.A.scorer[2].scores.uniqueFloat32 +
    " | B unique u1=" + report.B.scorer[1].scores.uniqueFloat32 + " u2=" + report.B.scorer[2].scores.uniqueFloat32);
}
main().catch(function (e) { console.error("DIAG FAILED:", e); process.exit(1); });

