// HW6 MF micro-diagnostic (diagnostic only, production code untouched).
// Same init factors + seed + first real TRAIN batch for A and B.
//   A: l2 = rawL2 * reg            (shipped week6 objective)
//   B: l2 = rawL2 * (reg / size)   (a05-matrix-factorization week5 objective)
// Measures MSE and L2 separately, their gradient norms separately, factor norms
// and raw dot-product spread before/after identical steps, and raw dots vs scores.
const fs = require("fs");
const path = require("path");
const tf = require("C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js");
const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const OUT = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\audit\\HW6_MF_MICRO_DIAG_2026-10-19.json";
const T0 = Date.now();
const BUDGET_MS = 110000;

const F = 16, EPOCHS = 30, LR = 0.01, REG = 0.05, BATCH = 512, SEED = 20261013;
const STEPS = 5;

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---- real data + chronological split (mirror of week6/data.js) ----
function loadSplit() {
  const text = fs.readFileSync(path.join(WEEK6, "u.data"), "utf8");
  const ratings = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const f = line.split("\t");
    if (f.length < 4) continue;
    ratings.push({ userId: parseInt(f[0]), movieId: parseInt(f[1]), rating: parseFloat(f[2]), timestamp: parseInt(f[3]) });
  }
  const byUser = new Map();
  for (const r of ratings) { if (!byUser.has(r.userId)) byUser.set(r.userId, []); byUser.get(r.userId).push(r); }
  const train = [], val = [], test = [];
  for (const [, list] of byUser) {
    const n = list.length; if (n < 5) continue;
    const sorted = list.slice().sort((a, b) => a.timestamp - b.timestamp || a.movieId - b.movieId);
    const nTrain = Math.floor(0.8 * n), nVal = Math.floor(0.1 * n);
    for (let i = 0; i < n; i++) (i < nTrain ? train : i < nTrain + nVal ? val : test).push(sorted[i]);
  }
  return { ratings, train, val, test };
}
function globalMeanOf(rows) { let s = 0; for (const r of rows) s += r.rating; return s / rows.length; }
function froNorm(arr) { let s = 0; for (const v of arr) s += v * v; return Math.sqrt(s); }
function stats(values) {
  let min = Infinity, max = -Infinity, sum = 0;
  for (const v of values) { if (v < min) min = v; if (v > max) max = v; sum += v; }
  const mean = sum / values.length;
  let sq = 0; for (const v of values) sq += (v - mean) * (v - mean);
  const sd = Math.sqrt(sq / values.length);
  return { n: values.length, min, max, mean, std: sd, unique32: new Set(values.map(Math.fround)).size };
}

const split = loadSplit();
const train = split.train;
const numUsers = Math.max.apply(null, split.ratings.map(r => r.userId));
let maxMovieId = 0, maxId = 0;
for (const line of fs.readFileSync(path.join(WEEK6, "u.item"), "utf8").split("\n")) {
  if (!line.trim()) continue;
  const id = parseInt(line.split("|")[0]);
  if (Number.isFinite(id)) maxId = Math.max(maxId, id);
}
maxMovieId = maxId;
const userRows = numUsers + 1, itemRows = maxMovieId + 1;
const candidateIds = Array.from(new Set(train.map(r => r.movieId))).sort((a, b) => a - b);
const globalMean = globalMeanOf(train);
const globalMeanF32 = Math.fround(globalMean);

// ---- identical initialization for A and B (same seed, same rand call order) ----
function makeInit() {
  const rand = mulberry32(SEED);
  const normal = () => { const u = Math.max(rand(), 1e-12), v = rand(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const uData = new Float32Array(userRows * F);
  for (let k = 0; k < uData.length; k++) uData[k] = normal() * 0.05;
  const iData = new Float32Array(itemRows * F);
  for (let k = 0; k < iData.length; k++) iData[k] = normal() * 0.05;
  // exact epoch-1 Fisher-Yates that production runs before the first batch
  const order = new Int32Array(train.length);
  for (let i = 0; i < order.length; i++) order[i] = i;
  for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); const t = order[i]; order[i] = order[j]; order[j] = t; }
  const uIdx = new Int32Array(BATCH), iIdx = new Int32Array(BATCH), target = new Float32Array(BATCH);
  for (let k = 0; k < BATCH; k++) { const row = train[order[k]]; uIdx[k] = row.userId; iIdx[k] = row.movieId; target[k] = row.rating; }
  return { uData, iData, uIdx, iIdx, target };
}
const init = makeInit();

function dotsFor(model, uids) {
  return tf.tidy(() => {
    const items = tf.gather(model.itemFactors, tf.tensor1d(Int32Array.from(candidateIds), "int32"));
    const out = {};
    for (const uid of uids) {
      const row = model.userFactors.slice([uid, 0], [1, F]);
      const dot = tf.matMul(items, row, false, true).squeeze();
      const dotArr = Array.from(dot.dataSync());
      out[uid] = { dot: stats(dotArr), dotMin: Math.min.apply(null, dotArr), dotMax: Math.max.apply(null, dotArr),
        scoreStats: stats(dotArr.map(d => Math.fround(d + globalMeanF32))) };
    }
    return out;
  });
}

function runVariant(label, l2Divisor) {
  const u = tf.variable(tf.tensor2d(init.uData, [userRows, F]));
  const i = tf.variable(tf.tensor2d(init.iData, [itemRows, F]));
  const model = { userFactors: u, itemFactors: i };
  const y = tf.tensor1d(init.target, "float32");
  const uIdxT = tf.tensor1d(init.uIdx, "int32");
  const iIdxT = tf.tensor1d(init.iIdx, "int32");

  const mseFn = () => tf.tidy(() => {
    const uu = tf.gather(u, uIdxT), ii = tf.gather(i, iIdxT);
    const pred = tf.sum(tf.mul(uu, ii), 1).add(globalMean);
    return tf.losses.meanSquaredError(y, pred);
  });
  const rawL2Fn = () => tf.tidy(() => u.square().sum().add(i.square().sum()));
  const mse0 = mseFn().dataSync()[0];
  const rawL20 = rawL2Fn().dataSync()[0];
  const l2Applied = rawL20 * (REG / l2Divisor);

  const gm = tf.variableGrads(mseFn, [u, i]);
  const gl = tf.variableGrads(rawL2Fn, [u, i]);
  const gMse = { user: froNorm(Array.from(gm.grads[0].dataSync())), item: froNorm(Array.from(gm.grads[1].dataSync())) };
  const gL2 = { user: froNorm(Array.from(gl.grads[0].dataSync())), item: froNorm(Array.from(gl.grads[1].dataSync())) };
  const gL2Applied = { user: gL2.user * (REG / l2Divisor), item: gL2.item * (REG / l2Divisor) };
  gm.grads[0].dispose(); gm.grads[1].dispose(); gm.value.dispose();
  gl.grads[0].dispose(); gl.grads[1].dispose(); gl.value.dispose();

  const before = { userFro: froNorm(init.uData), itemFro: froNorm(init.iData), dots: dotsFor(model, [1, 2]) };

  const optimizer = tf.train.adam(LR);
  const cost0 = [];
  for (let s = 0; s < STEPS; s++) {
    const c = optimizer.minimize(() => tf.tidy(() => {
      const uu = tf.gather(u, uIdxT), ii = tf.gather(i, iIdxT);
      const pred = tf.sum(tf.mul(uu, ii), 1).add(globalMean);
      const mse = tf.losses.meanSquaredError(y, pred);
      const l2 = u.square().sum().add(i.square().sum()).mul(REG / l2Divisor);
      return mse.add(l2);
    }), true, [u, i]);
    cost0.push(c ? c.dataSync()[0] : null);
    if (c) c.dispose();
  }
  const after = {
    userFro: froNorm(Array.from(u.dataSync())), itemFro: froNorm(Array.from(i.dataSync())),
    dots: dotsFor(model, [1, 2])
  };
  u.dispose(); i.dispose(); y.dispose(); uIdxT.dispose(); iIdxT.dispose(); optimizer.dispose();
  return { label, l2Divisor, mse0, rawL20, l2Applied, ratio_l2_over_mse: l2Applied / mse0,
    gradNorms: { mse: gMse, l2raw: gL2, l2applied: gL2Applied },
    gradRatio_l2applied_over_mse: { user: gL2Applied.user / gMse.user, item: gL2Applied.item / gMse.item },
    before, after, stepCosts: cost0 };
}

const report = {
  generated_at: new Date().toISOString(),
  scope: "bounded micro-diagnostic on one real TRAIN batch; NOT final HW6 metrics and NOT a browser WebGL run",
  backend: tf.getBackend(), tfVersion: tf.version,
  config: { factors: F, epochs: EPOCHS, lr: LR, reg: REG, batchSize: BATCH, seed: SEED, steps: STEPS },
  data: { trainSize: train.length, valSize: split.val.length, testSize: split.test.length, users: numUsers,
    maxMovieId, candidatePool: candidateIds.length, globalMean, globalMeanFloat32: globalMeanF32 },
  constantMeanBaseline: {
    train: Math.sqrt(split.train.reduce((s, r) => s + (r.rating - globalMean) ** 2, 0) / split.train.length),
    val: Math.sqrt(split.val.reduce((s, r) => s + (r.rating - globalMean) ** 2, 0) / split.val.length),
    test: Math.sqrt(split.test.reduce((s, r) => s + (r.rating - globalMean) ** 2, 0) / split.test.length)
  },
  elapsedMsBeforeRun: Date.now() - T0
};

if (Date.now() - T0 > BUDGET_MS) { fs.writeFileSync(OUT, JSON.stringify(report, null, 2)); console.error("budget exceeded before training"); process.exit(3); }

report.A_fullL2 = runVariant("A_full_L2", 1);
report.TOPIC = null;
report.B_l2overBatch = runVariant("B_l2_over_batch", BATCH);
report.elapsedMsTotal = Date.now() - T0;
report.withinBudget = report.elapsedMsTotal <= BUDGET_MS;
delete report.TOPIC;

fs.writeFileSync(OUT, JSON.stringify(report, null, 2));
console.log("WROTE " + OUT + " elapsed=" + report.elapsedMsTotal + "ms");
console.log("A: mse0=" + report.A_fullL2.mse0.toFixed(6) + " rawL2=" + report.A_fullL2.rawL20.toFixed(3) + " l2applied=" + report.A_fullL2.l2Applied.toFixed(3) + " ratio=" + report.A_fullL2.ratio_l2_over_mse.toFixed(3));
console.log("B: mse0=" + report.B_l2overBatch.mse0.toFixed(6) + " rawL2=" + report.B_l2overBatch.rawL20.toFixed(3) + " l2applied=" + report.B_l2overBatch.l2Applied.toFixed(6) + " ratio=" + report.B_l2overBatch.ratio_l2_over_mse.toFixed(6));
console.log("grad ratio l2/mse  A user=" + report.A_fullL2.gradRatio_l2applied_over_mse.user.toFixed(3) + " item=" + report.A_fullL2.gradRatio_l2applied_over_mse.item.toFixed(3) + " | B user=" + report.B_l2overBatch.gradRatio_l2applied_over_mse.user.toFixed(6));
console.log("after " + STEPS + " steps factorFro  A u=" + report.A_fullL2.after.userFro.toFixed(4) + " i=" + report.A_fullL2.after.itemFro.toFixed(4) + "  B u=" + report.B_l2overBatch.after.userFro.toFixed(4) + " i=" + report.B_l2overBatch.after.itemFro.toFixed(4));
console.log("u1 raw dot before A std=" + report.A_fullL2.before.dots[1].dot.std + " after A std=" + report.A_fullL2.after.dots[1].dot.std + " after B std=" + report.B_l2overBatch.after.dots[1].dot.std);

