// HW6 MF L2 batch-scale check (diagnostic only; production code untouched).
// Runs the REAL shipped hw6TrainMf with a stub Adam optimizer that applies no
// updates, so the factor variables are constant during the whole pass. For each
// real TRAIN batch the shipped loss is evaluated and we recover the coefficient
// that multiplies the raw L2 sum:  c = (cost - mse) / rawL2.
// Correct behaviour: c == reg / actualBatchSize, including the last partial batch.
const fs = require("fs");
const path = require("path");
const vm = require("vm");
const WEEK6 = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\week6";
const realTf = require("C:\\Users\\pc01\\AppData\\Local\\Temp\\opencode\\tf.min.js");
const OUT = "C:\\Users\\pc01\\Documents\\RecSys-LLMs\\audit\\HW6_MF_L2_BATCH_SCALE_CHECK_2026-10-20.json";
const REG = 0.05;

function makeElement(id) {
  return { id: id, textContent: "", innerHTML: "", value: "0.85", disabled: false, style: {},
    classList: { _s: {}, add: function (c) { this._s[c] = true; }, remove: function (c) { delete this._s[c]; }, contains: function (c) { return !!this._s[c]; } },
    addEventListener: function () {}, appendChild: function () {}, setAttribute: function () {},
    querySelector: function () { return null; }, querySelectorAll: function () { return []; } };
}
const els = new Map(); function getEl(id) { if (!els.has(id)) els.set(id, makeElement(id)); return els.get(id); }

const captured = { batches: [] };

// Proxy of the real tf: same math, but the optimizer records instead of updating.
const tfp = Object.create(realTf);
tfp.train = Object.create(realTf.train);
tfp.losses = Object.create(realTf.losses);
let lastMse = null;
tfp.losses.meanSquaredError = function (a, b) {
  const v = realTf.losses.meanSquaredError(a, b);
  lastMse = v.dataSync()[0];
  return v;
};
tfp.train.adam = function () {
  return {
    minimize: function (fn, returnCost) {
      const cost = fn();
      const c = cost.dataSync()[0];
      captured.batches.push({ cost: c, mse: lastMse });
      return returnCost ? cost : null;
    },
    dispose: function () {},
  };
};

const sandbox = {
  console: console, tf: tfp, setTimeout: setTimeout, clearTimeout: clearTimeout,
  fetch: async function (url) { const t = fs.readFileSync(path.join(WEEK6, String(url).split("?")[0]), "utf8"); return { ok: true, status: 200, text: async function () { return t; } }; },
  document: { readyState: "loading", getElementById: getEl, addEventListener: function () {}, createElement: function () { return makeElement(); }, querySelector: function () { return null; }, querySelectorAll: function () { return []; }, body: makeElement("body") },
  navigator: { userAgent: "node" }, performance: { now: function () { return Date.now(); } },
  URL: URL, URLSearchParams: URLSearchParams,
  requestAnimationFrame: function (cb) { return setTimeout(cb, 0); }, cancelAnimationFrame: clearTimeout,
};
const ctx = vm.createContext(sandbox);
vm.runInContext("window=globalThis; self=globalThis;", ctx);
vm.runInContext(fs.readFileSync(path.join(WEEK6, "data.js"), "utf8"), ctx, { filename: "data.js" });
vm.runInContext(fs.readFileSync(path.join(WEEK6, "graph.js"), "utf8"), ctx, { filename: "graph.js" });
vm.runInContext(fs.readFileSync(path.join(WEEK6, "script.js"), "utf8"), ctx, { filename: "script.js" });
function ev(code) { return vm.runInContext(code, ctx); }
function eva(code) { return vm.runInContext("(async()=>{ return (" + code + "); })()", ctx); }

async function check(sliceLen, batchSize, label) {
  ev("MF_CONFIG.epochs = 1; MF_CONFIG.batchSize = " + batchSize + ";");
  const train = ev("HW6_SPLIT.train") || null;
  // Build the split once from real data.
  const ready = ev("typeof HW6_SPLIT !== 'undefined' && HW6_SPLIT.train.length > 0");
  if (!ready) throw new Error("split not ready");
  captured.batches = [];
  const model = await eva("hw6TrainMf(HW6_SPLIT.train.slice(0, " + sliceLen + "), null)");
  const rawL2 = ev("(function(){ var m=HW6_MF_MODEL; var u=m.userFactors.dataSync(), i=m.itemFactors.dataSync();" +
    " var su=0; for (var k=0;k<u.length;k++) su+=u[k]*u[k]; var si=0; for (var k=0;k<i.length;k++) si+=i[k]*i[k]; return su+si; })()");
  const rows = [];
  for (let b = 0; b < captured.batches.length; b++) {
    const rec = captured.batches[b];
    const expectedSize = Math.min(batchSize, sliceLen - b * batchSize);
    const implied = (rec.cost - rec.mse) / rawL2;
    rows.push({ batch: b, expectedSize: expectedSize, impliedL2Coefficient: implied,
      expectedCoefficient: REG / expectedSize,
      ratio: implied / (REG / expectedSize),
      absError: Math.abs(implied - REG / expectedSize) });
  }
  const maxErr = Math.max.apply(null, rows.map(r => r.absError));
  const ok = rows.every(r => r.absError < 1e-9 * Math.max(1, r.expectedCoefficient) || r.absError < 1e-12);
  if (model) { ev("hw6DisposeMf()"); }
  return { label: label, sliceLen: sliceLen, batchSize: batchSize, batches: rows.length,
    lastBatchSize: sliceLen % batchSize || batchSize, maxAbsError: maxErr, pass: ok };
}

(async function () {
  await eva("hw6InitTf()");
  await eva("loadData()");
  ev("(function(){ var s = splitByTimestamp(); HW6_SPLIT.train = s.train; HW6_SPLIT.val = s.val; HW6_SPLIT.test = s.test;" +
     " HW6_MAX_MOVIE_ID = movies.reduce(function(m,x){ return Math.max(m, x.id); }, 0); hw6BuildSplitIndices(HW6_SPLIT); return true; })()");
  const trainLen = ev("HW6_SPLIT.train.length");
  const partial = await check(1300, 512, "partial_last_batch");   // 512 + 512 + 276
  const full = await check(1024, 512, "exact_multiple");          // 512 + 512
  const one = await check(100, 512, "single_small_batch");        // 100
  const report = { generated_at: new Date().toISOString(),
    scope: "controlled code check of the shipped L2 scale, not final HW6 metrics",
    trainLength: trainLen, reg: REG,
    coefficient_recovered: "c = (cost - mse) / rawL2sum from the real shipped loss",
    partial_last_batch: partial, exact_multiple: full, single_small_batch: one,
    overall: partial.pass && full.pass && one.pass };
  fs.writeFileSync(OUT, JSON.stringify(report, null, 2));
  console.log("WROTE " + OUT);
  console.log("partial: batches=" + partial.batches + " last=" + partial.lastBatchSize + " maxErr=" + partial.maxAbsError.toExponential(3) + " pass=" + partial.pass);
  console.log("exact:   batches=" + full.batches + " maxErr=" + full.maxAbsError.toExponential(3) + " pass=" + full.pass);
  console.log("single:  batches=" + one.batches + " maxErr=" + one.maxAbsError.toExponential(3) + " pass=" + one.pass);
  console.log("OVERALL " + report.overall);
})().catch(function (e) { console.error("CHECK FAILED:", e && e.message ? e.message : e); process.exit(1); });

